insert into countries ("iso2", "iso_numeric", "slug", "name", "status", "plate", "headline", "intro", "candidates", "shared_traditions", "centroid_lon", "centroid_lat")
  select "iso2", "iso_numeric", "slug", "name", "status", "plate", "headline", "intro", "candidates", "shared_traditions", "centroid_lon", "centroid_lat" from jsonb_populate_recordset(null::countries, $cp$[{"iso2":"IN","iso_numeric":"356","slug":"india","name":"India","status":"active","plate":"Plate II","headline":"India is not one story. It is thousands of stories.","intro":"Five traditions documented in depth by our editors, several with roots that cross today's borders into Pakistan and Nepal — and a growing shelf of research passports drawn from India's Geographical Indications register and UNESCO's lists, each marked for review.","candidates":[{"name":"Pattachitra","note":"Odisha"},{"name":"Gond painting","note":"Madhya Pradesh"},{"name":"Kalamkari","note":"Andhra Pradesh · Telangana"},{"name":"Kantha","note":"West Bengal"},{"name":"Mandana","note":"Rajasthan"},{"name":"Rogan","note":"Gujarat"},{"name":"Chamba Rumal","note":"Himachal Pradesh"},{"name":"Aipan","note":"Uttarakhand"},{"name":"Handloom weaving","note":"Assam"}],"shared_traditions":[],"centroid_lon":78.9,"centroid_lat":22.5},{"iso2":"AE","iso_numeric":"784","slug":"united-arab-emirates","name":"United Arab Emirates","status":"introductory","plate":"Plate III","headline":"Not only a destination. A bridge.","intro":"Where many cultures already meet. An introductory collection built only from UNESCO and government records, so the bridge between India and the world begins on firm ground.","candidates":[{"name":"Al Talli","note":"Traditional embroidery skills, inscribed on UNESCO's Representative List in 2022. Passport in preparation.","sources":["unesco-talli"]}],"shared_traditions":[],"centroid_lon":54.3,"centroid_lat":23.9},{"iso2":"GH","iso_numeric":"288","slug":"ghana","name":"Ghana","status":"documenting","plate":"Plate IV","headline":"Stories being documented.","intro":"A future collection. Nothing will be published here until sources have been verified and communities consulted.","candidates":[{"name":"Kente","note":"Candidate tradition — research not yet begun."}],"shared_traditions":[],"centroid_lon":-1,"centroid_lat":7.9},{"iso2":"JP","iso_numeric":"392","slug":"japan","name":"Japan","status":"documenting","plate":"Plate V","headline":"Stories being documented.","intro":"A future collection. Japan already appears in this archive as a destination: the Mithila Museum in Tokamachi holds one of the largest collections of Mithila painting outside India.","candidates":[{"name":"Sashiko","note":"Candidate tradition — research not yet begun."}],"shared_traditions":["madhubani-painting"],"centroid_lon":138.2,"centroid_lat":36.2},{"iso2":"MX","iso_numeric":"484","slug":"mexico","name":"Mexico","status":"documenting","plate":"Plate VI","headline":"Stories being documented.","intro":"A future collection. One documented attribution case is queued for research.","candidates":[{"name":"Otomi textile traditions of Tenango de Doria","note":"Candidate tradition. In June 2019 Mexico's culture secretary wrote to a fashion house asking it to explain its use of Tenango embroidery — a case we will document in full before publishing.","sources":["malaymail-tenango-2019"]}],"shared_traditions":[],"centroid_lon":-102.5,"centroid_lat":23.6},{"iso2":"PK","iso_numeric":"586","slug":"pakistan","name":"Pakistan","status":"shared","plate":"Shared","headline":"Traditions don't stop at borders.","intro":"No dedicated collection yet. Pakistan appears in this archive through traditions shared across the 1947 border — Ajrakh in Sindh and Phulkari in Punjab — which we refuse to file under one modern country alone.","candidates":[],"shared_traditions":["ajrakh","phulkari"],"centroid_lon":69.3,"centroid_lat":30},{"iso2":"NP","iso_numeric":"524","slug":"nepal","name":"Nepal","status":"shared","plate":"Shared","headline":"Mithila spans two countries.","intro":"No dedicated collection yet. The Mithila cultural region extends from northern Bihar into Nepal's Madhesh, around Janakpur, so the Madhubani passport is listed here too.","candidates":[],"shared_traditions":["madhubani-painting"],"centroid_lon":84.1,"centroid_lat":28.4}]$cp$::jsonb)
  on conflict do nothing;

