insert into communities ("id", "name", "description")
  select "id", "name", "description" from jsonb_populate_recordset(null::communities, $cp$[{"id":"charmakar","name":"Charmakar leather-working communities","description":"Leather-working caste groups of Maharashtra and Karnataka with whom the making of Kolhapuri chappals is predominantly associated, then and now."},{"id":"mithila-women","name":"Women painters of Mithila","description":"Women of the Mithila region, across several caste communities, who painted the walls and floors of homes for rituals and weddings. Early accounts centred Brahmin and Kayastha styles and overlooked others."},{"id":"punjabi-women","name":"Women of undivided Punjab","description":"Women across Punjab — a region now divided between India and Pakistan — who embroidered phulkari and bagh for family and ceremonial use."},{"id":"warli","name":"Warli (Varli) Adivasi community","description":"An Adivasi (Indigenous) community of the coastal and hill districts on the Maharashtra–Gujarat border, whose ritual wall painting is known as Warli painting."},{"id":"khatri","name":"Khatri dyer-printer communities","description":"Families of dyers and block-printers in Sindh and Kutch (and in Barmer) associated with ajrakh. Many Kutch families trace their origins to Sindh."},{"id":"bedouin-women-uae","name":"Bedouin women of rural UAE communities","description":"Women who spin, dye and weave Al Sadu, learning by watching and through gatherings of weavers; men traditionally shear the animals."}]$cp$::jsonb)
  on conflict do nothing;

