"Madhubani_paintings_(Madhubani_Railway_Station).jpg","commons_hash":"f/fd","url":null,"width":4160,"height":3120,"alt":"Walls of Madhubani railway station covered in large Madhubani paintings.","caption":"Madhubani paintings on the walls of Madhubani railway station (2021).","credit":"Photo: Sntshkumar750","license":"CC BY-SA 4.0","license_url":"https://creativecommons.org/licenses/by-sa/4.0/","source_page":"https://commons.wikimedia.org/wiki/File:Madhubani_paintings_(Madhubani_Railway_Station).jpg","kind":"photograph","documentary":true},{"id":"madhubani-artist","commons_file":"Dilli_Haat_Madhubani_Mithila_Painting_Artist.jpg","commons_hash":"d/d8","url":null,"width":3888,"height":2592,"alt":"A Mithila painter drawing fine lines on paper at a craft market stall, with finished paintings behind him.","caption":"A Mithila painter at work, Dilli Haat, New Delhi (2012).","credit":"Photo: Pallav.journo","license":"CC BY-SA 4.0","license_url":"https://creativecommons.org/licenses/by-sa/4.0/","source_page":"https://commons.wikimedia.org/wiki/File:Dilli_Haat_Madhubani_Mithila_Painting_Artist.jpg","kind":"photograph","documentary":true},{"id":"phulkari-osterley","commons_file":"A_Phulkari_with_traditional_flower_pattern_on_unworked_background.jpg","commons_hash":"c/cb","url":null,"width":3372,"height":4466,"alt":"A phulkari draped on a display figure: red embroidered flowers scattered across a cream ground.","caption":"Phulkari with a traditional flower pattern on an unworked ground, Punjab. Karun Thakar Collection, shown at Osterley House.","credit":"Photo: Chiswick Chap","license":"CC BY-SA 4.0","license_url":"https://creativecommons.org/licenses/by-sa/4.0/","source_page":"https://commons.wikimedia.org/wiki/File:A_Phulkari_with_traditional_flower_pattern_on_unworked_background.jpg","kind":"museum-object","documentary":true},{"id":"phulkari-patiala-1900","commons_file":"Photograph_of_a_Patiala_Punjabi_woman_in_Phulkari,_ca.1900.jpg","commons_hash":"0/04","url":null,"width":634,"height":998,"alt":"Archival photograph of a woman in Patiala wearing a phulkari, around 1900.","caption":"A woman in Patiala wearing phulkari, c. 1900. Photographer unknown.","credit":"Photographer unknown","license":"Public domain","license_url":null,"source_page":"https://commons.wikimedia.org/wiki/File:Photograph_of_a_Patiala_Punjabi_woman_in_Phulkari,_ca.1900.jpg","kind":"archival","documentary":true},{"id":"phulkari-rajpura","commons_file":"Women_embroidering_Phulkari_in_Rajpura,_Punjab_(India),_2015.jpg","commons_hash":"2/2e","url":null,"width":2148,"height":1017,"alt":"Women's hands working on a bright pink and orange phulkari, with an embroidery hoop and a cream cloth beside it.","caption":"Women embroidering phulkari in Rajpura, Punjab, 2015.","credit":"Photo: Sheebamadanloewinger","license":"CC BY-SA 4.0","license_url":"https://creativecommons.org/licenses/by-sa/4.0/","source_page":"https://commons.wikimedia.org/wiki/File:Women_embroidering_Phulkari_in_Rajpura,_Punjab_(India),_2015.jpg","kind":"photograph","documentary":true},{"id":"phulkari-cleveland","commons_file":"India,_Punjab,_19th_century_-_Head_Shawl_(\"Phulkari\")_-_1940.595_-_Cleveland_Museum_of_Art.jpg","commons_hash":"b/bc","url":null,"width":3400,"height":1945,"alt":"A phulkari head shawl with a lattice of deep red lines on cream silk embroidery, framed by golden borders.","caption":"Head shawl (phulkari), Punjab, 19th century. Cleveland Museum of Art, 1940.595.","credit":"Cleveland Museum of Art","license":"CC0 1.0","license_url":"https://creativecommons.org/publicdomain/zero/1.0/","source_page":"https://commons.wikimedia.org/wiki/File:India,_Punjab,_19th_century_-_Head_Shawl_(%22Phulkari%22)_-_1940.595_-_Cleveland_Museum_of_Art.jpg","kind":"photograph","documentary":true},{"id":"phulkari-shawl","commons_file":"Embroidery_on_a_shawl_from_Punjab_01.jpg","commons_hash":"0/09","url":null,"width":5472,"height":3648,"alt":"Close-up of dense geometric embroidery in pink, blue, green and purple on a Punjabi shawl.","caption":"Embroidery on a shawl from Punjab.","credit":"Photo: Kritzolina","license":"CC BY-SA 4.0","license_url":"https://creativecommons.org/licenses/by-sa/4.0/","source_page":"https://commons.wikimedia.org/wiki/File:Embroidery_on_a_shawl_from_Punjab_01.jpg","kind":"photograph","documentary":true},{"id":"warli-sgnp","commons_file":"Warli_art_on_a_house_wall_at_Sanjay_Gandhi_National_Park.jpg","commons_hash":"b/b9","url":null,"width":1892,"height":2588,"alt":"White Warli figures painted on the mud wall of a house.","caption":"Warli painting on a house wall in an Adivasi settlement inside Sanjay Gandhi National Park, Mumbai (2022).","credit":"Photo: Blackstardust","license":"CC BY-SA 4.0","license_url":"https://creativecommons.org/licenses/by-sa/4.0/","source_page":"https://commons.wikimedia.org/wiki/File:Warli_art_on_a_house_wall_at_Sanjay_Gandhi_National_Park.jpg","kind":"photograph","documentary":true},{"id":"warli-mashe","commons_file":"A_Warli_painting_by_Jivya_Soma_Mashe,_Thane_district.jpg","commons_hash":"a/a6","url":null,"width":1600,"height":1200,"alt":"Detail of a Warli painting showing tarpa dancers circling a musician.","caption":"Detail of a work by Jivya Soma Mashe: tarpa dancers around a musician (2003). Museum Kunstpalast, Düsseldorf.","credit":"Photo: Jean-Pierre Dalbéra","license":"CC BY 2.0","license_url":"https://creativecommons.org/licenses/by/2.0/","source_page":"https://commons.wikimedia.org/wiki/File:A_Warli_painting_by_Jivya_Soma_Mashe,_Thane_district.jpg","kind":"artwork","documentary":true},{"id":"warli-omr","commons_file":"Warli_painting.jpg","commons_hash":"a/a3","url":null,"width":3000,"height":3000,"alt":"A Warli painting in white on an earth-brown ground: a ring of dancing figures inside a circle.","caption":"Warli painting.","credit":"Photo: Omrmankar","license":"CC BY-SA 4.0","license_url":"https://creativecommons.org/licenses/by-sa/4.0/","source_page":"https://commons.wikimedia.org/wiki/File:Warli_painting.jpg","kind":"artwork","documentary":true},{"id":"ajrak-print-4","commons_file":"Ajrak_Print_4.jpg","commons_hash":"d/dc","url":null,"width":4160,"height":3120,"alt":"Blue block-printed cloth with rows of red and cream motifs.","caption":"Ajrakh-printed cloth in blue, red and cream.","credit":"Photo: SMarndi","license":"CC BY-SA 4.0","license_url":"https://creativecommons.org/licenses/by-sa/4.0/","source_page":"https://commons.wikimedia.org/wiki/File:Ajrak_Print_4.jpg","kind":"photograph","documentary":true},{"id":"ajrak-print-1","commons_file":"Ajrak_Print_1.jpg","commons_hash":"e/e8","url":null,"width":3120,"height":4160,"alt":"A bolster covered in ajrakh-printed cloth.","caption":"A bolster with an ajrakh-printed cover.","credit":"Photo: SMarndi","license":"CC BY-SA 4.0","license_url":"https://creativecommons.org/licenses/by-sa/4.0/","source_page":"https://commons.wikimedia.org/wiki/File:Ajrak_Print_1.jpg","kind":"photograph","documentary":true},{"id":"ajrak-sindh","commons_file":"Ajrak.jpg","commons_hash":"2/2a","url":null,"width":4137,"height":1821,"alt":"An ajrak from Sindh in deep red, black and white, with repeating medallion and lattice patterns.","caption":"Ajrak shawls, Sindh (2010).","credit":"Photo: Ahub1988","license":"CC BY-SA 3.0","license_url":"https://creativecommons.org/licenses/by-sa/3.0/","source_page":"https://commons.wikimedia.org/wiki/File:Ajrak.jpg","kind":"photograph","documentary":true},{"id":"sadu-majlis","commons_file":"Majlis_in_Sadu_style.jpg","commons_hash":"2/20","url":null,"width":1102,"height":557,"alt":"Floor seating and cushions in a majlis, upholstered in red with Sadu-style striped bands.","caption":"Majlis furnishings in the Sadu style, UAE (2025). Whether the fabric is hand-woven Al Sadu is not recorded.","credit":"Photo: Ashley Columbus","license":"CC0 1.0","license_url":"https://creativecommons.org/publicdomain/zero/1.0/","source_page":"https://commons.wikimedia.org/wiki/File:Majlis_in_Sadu_style.jpg","kind":"photograph","documentary":true}]$cp$::jsonb)
  on conflict do nothing;

insert into traditions ("id", "slug", "passport_no", "status", "maturity", "name", "display_title", "tagline", "category", "techniques", "collection_iso2", "region_label", "summary", "intro", "accent", "motif", "hero_media_id", "gallery", "periods", "voices_note", "collaboration_notes", "editorial")
  select "id", "slug", "passport_no", "status", "maturity", "name", "display_title", "tagline", "category", "techniques", "collection_iso2", "region_label", "summary", "intro", "accent", "motif", "hero_media_id", "gallery", "periods", "voices_note", "collaboration_notes", "editorial" from jsonb_populate_recordset(null::traditions, $cp$[{"id":"trad-kolhapuri","slug":"kolhapuri-chappal","passport_no":"001","status":"published","maturity":"researched","name":"Kolhapuri Chappal","display_title":"The Kolhapuri Chappal","tagline":"A craft older than the runway.","category":"footwear","techniques":["Hand-stitched leather","Braided leather uppers","Leather tanning"],"collection_iso2":"IN","region_label":"Maharashtra & Karnataka, India","summary":"Flat, open-toed, hand-stitched leather sandals made across eight districts of Maharashtra and Karnataka — and, in June 2025, the subject of one of fashion's most visible attribution debates.","intro":"Long before it reached a Milan runway, the Kolhapuri chappal was everyday footwear: buffalo-hide leather, hand-stitched without nails, braided across the instep and finished with a loop for the big toe. Its name belongs to a city. Its making belongs to communities of leather-workers on both sides of the Maharashtra–Karnataka border.","accent":"terracotta","motif":"kolhapuri","hero_media_id":"bata-chappal-445","gallery":["bata-chappal-445","kolhapur-shop-1","kolhapur-shop-3","bata-chappal-453"],"periods":["Medieval (claimed)","Princely Kolhapur","20th century","2009–2019 GI","2025 runway","2026 collaboration"],"voices_note":"We have not yet recorded interviews with Kolhapuri makers. Rather than paraphrase artisans from press coverage, this space stays empty until makers choose to speak for themselves here.","collaboration_notes":["Name the tradition — 'Kolhapuri chappal' — wherever the design is shown, from the first presentation.","Only goods made in the eight registered districts can carry the Kolhapuri Chappal name.","Work through the GI proprietors and makers' organisations, and agree on fair payment and credit before production.","Link this passport, or its QR code, beside the product so its story travels with it."],"editorial":{"lastReviewed":"2026-11-17","reviewedBy":"Culture Passport editorial desk (seed research)","notes":"Flagship passport. Historical claims before 2009 rest on secondary accounts and are labelled accordingly. Case-study facts are drawn from court reporting, registry records and contemporaneous press.","openQuestions":["Archival evidence for the chappal's age before the 20th century.","Which Kolhapur ruler(s) supported tanning, and when.","How benefits from the 2025–26 collaboration reach makers.","Community self-identification, to be recorded with makers."]}},{"id":"trad-madhubani","slug":"madhubani-painting","passport_no":"002","status":"published","maturity":"researched","name":"Madhubani Painting","display_title":"Madhubani · Mithila Painting","tagline":"From the walls of a wedding room to the walls of the world.","category":"painting","techniques":["Line work (kachni)","Filled colour (bharni)","Wall and floor painting","Painting on paper"],"collection_iso2":"IN","region_label":"Mithila — Bihar, India & Nepal","summary":"A painting tradition of the Mithila region — northern Bihar and neighbouring Nepal — made for centuries by women on the walls of homes, and carried onto paper and into the world in the 20th century.","intro":"Mithila painting began as something made for a room and an occasion: a wedding chamber, a festival, a threshold. Women drew gods, fish, birds and lotus vines in dense double lines. When the world met it, first through a colonial officer's camera and then through paper sold in Delhi, its makers' names travelled more slowly than its images.","accent":"burgundy","motif":"madhubani","hero_media_id":"madhubani-station","gallery":["madhubani-station","madhubani-artist","madhubani-0028","madhubani-0103"],"periods":["Legend","1934 earthquake","1960s drought","1980s Japan","2007 GI"],"voices_note":"The names above are public honours. We have not recorded interviews, and we do not attribute quotations to painters from secondary sources.","collaboration_notes":["Credit the painter by name, not only the style.","Say 'Mithila' as well as 'Madhubani' — the region crosses into Nepal.","Don't sell printed reproductions as hand painting.","The GI register lists authorised users — a starting point for finding registered painters."],"editorial":{"lastReviewed":"2026-11-17","reviewedBy":"Culture Passport editorial desk (seed research)","notes":"Researched starter passport. Materials and process details still need practitioner review.","openQuestions":["Accounts of Dalit painting traditions in Mithila, from practitioners themselves.","Current renewal status of the GI.","Practices on the Nepal side of the region."]}},{"id":"trad-phulkari","slug":"phulkari","passport_no":"003","status":"published","maturity":"starter","name":"Phulkari","display_title":"Phulkari","tagline":"Flower work, stitched from the back.","category":"embroidery","techniques":["Darning stitch","Silk floss (pat) on khaddar"],"collection_iso2":"IN","region_label":"Punjab — India & Pakistan","summary":"Embroidery of undivided Punjab — silk floss darned into hand-woven cotton from the reverse — made by women for weddings and family life, on both sides of a border drawn in 1947.","intro":"Phulkari means flower work. It was made by women in Punjab, a region that since 1947 has been divided between India and Pakistan. Untwisted silk floss is darned into hand-woven cotton from the back of the cloth, so the pattern appears on the front: sometimes scattered flowers, sometimes — in a bagh, a 'garden' — the whole cloth covered.","accent":"mustard","motif":"phulkari","hero_media_id":"phulkari-rajpura","gallery":["phulkari-rajpura","phulkari-cleveland","phulkari-patiala-1900","phulkari-shawl"],"periods":["Undated origins","c. 1900","1947 Partition","2010 GI","2017 Philadelphia"],"voices_note":"We have not yet recorded embroiderers' own accounts. Museum catalogues describe many historic phulkari as made by anonymous women — a gap this passport will not fill by inventing names.","collaboration_notes":["Say 'Punjab', not only 'India' — the tradition is shared with Pakistan.","Hand-embroidered and machine-printed phulkari are different products; label them honestly.","Credit embroiderers by name where they wish to be named."],"editorial":{"lastReviewed":"2026-11-17","reviewedBy":"Culture Passport editorial desk (seed research)","notes":"Starter passport: technique, GI and museum history are sourced; pre-1900 history is deliberately left undated.","openQuestions":["Reliable dating for early phulkari.","Exact Rajasthan coverage of the GI.","Practitioners' accounts from both Punjabs."]}},{"id":"trad-warli","slug":"warli-painting","passport_no":"004","status":"published","maturity":"editorial-draft","name":"Warli Painting","display_title":"Warli Painting","tagline":"A circle, a triangle, a community.","category":"painting","techniques":["Wall painting","Painting on paper and canvas"],"collection_iso2":"IN","region_label":"Maharashtra–Gujarat border, India","summary":"The ritual wall painting of the Warli Adivasi community of the Maharashtra–Gujarat border — now one of India's most reproduced visual languages, and one of its least credited.","intro":"Figures made of two triangles and a circle; dancers spiralling around a musician; fields, animals and spirits on an earthen wall. Warli painting belongs to the Warli community. It is now printed on mugs and murals far from Dahanu — often without the community's name.","accent":"forest","motif":"warli","hero_media_id":"warli-sgnp","gallery":["warli-sgnp","warli-mashe","warli-omr"],"periods":["Ritual wall painting","1970s paper","1989 Paris","2014 GI"],"voices_note":"Editorial draft. No interviews have been recorded; we will not publish process details until Warli painters have reviewed them.","collaboration_notes":["Name the Warli community, not just 'tribal art'.","Commission Warli painters rather than reproducing the style.","Contact the GI proprietor before using 'Warli' commercially."],"editorial":{"lastReviewed":"2026-11-17","reviewedBy":"Culture Passport editorial desk (seed research)","notes":"Editorial draft. Only GI, exhibition and award facts are documented; meaning, materials and process await community review.","openQuestions":["Ritual meanings and motif names, from Warli painters.","Who may paint, and on what occasions.","Documented cases of uncredited commercial use."]}},{"id":"trad-ajrakh","slug":"ajrakh","passport_no":"005","status":"published","maturity":"editorial-draft","name":"Ajrakh","display_title":"Ajrakh · Ajrak","tagline":"Indigo and madder, printed on both sides of a border.","category":"textile","techniques":["Hand block printing","Resist printing","Natural dyeing"],"collection_iso2":"IN","region_label":"Kutch & Barmer, India · Sindh, Pakistan","summary":"A resist-printed, naturally dyed cloth shared by Sindh in Pakistan and Kutch and Barmer in India, carried across the region by Khatri printing families.","intro":"Ajrakh is printed, washed, dyed, printed again — in indigo, madder red, black and white, in repeating stars and lattices. It is worn in Sindh, printed in Kutch and Barmer, and claimed by many origin stories at once. This passport is an editorial draft: it records what is documented and marks the rest.","accent":"indigo","motif":"ajrakh","hero_media_id":"ajrak-sindh","gallery":["ajrak-sindh","ajrak-print-4","ajrak-print-1"],"periods":["Indus (claimed)","16th-century migration (cited)","2001 earthquake","2024 GI"],"voices_note":"Editorial draft. Process steps are summarised from secondary sources and await review by printers in Ajrakhpur and Sindh.","collaboration_notes":["Say where it was printed — Kutch, Barmer or Sindh — and by whom.","Digital prints of ajrakh patterns are not ajrakh; label them as inspired by it.","The Kutch GI does not cover Sindhi ajrak; credit both traditions."],"editorial":{"lastReviewed":"2026-11-17","reviewedBy":"Culture Passport editorial desk (seed research)","notes":"Editorial draft. GI and relocation facts are documented; process, meaning and early history await practitioner review on both sides of the border.","openQuestions":["Process steps, from printers.","Sindhi institutions' account of ajrak.","Documented cases of uncredited commercial use."]}},{"id":"trad-sadu","slug":"al-sadu","passport_no":"006","status":"published","maturity":"starter","name":"Al Sadu","display_title":"Al Sadu","tagline":"Bands of black, white and red, woven on the ground.","category":"weaving","techniques":["Drop-spindle spinning","Floor-loom weaving","Warp-faced plain weave"],"collection_iso2":"AE","region_label":"Rural communities, United Arab Emirates","summary":"A traditional weaving of Bedouin women in the UAE's rural communities — spun on a drop spindle, woven on a floor loom, in narrow geometric bands — inscribed by UNESCO in 2011 and moved to its Representative List in New Delhi in 2025.","intro":"Al Sadu is the first passport in the UAE collection, and the archive's bridge. Everything here comes from UNESCO's own decisions and from government heritage records, because an introduction should begin on firm ground.","accent":"teal","motif":"sadu","hero_media_id":"sadu-majlis","gallery":["sadu-majlis"],"periods":["2011 urgent safeguarding","2020 report","2025 New Delhi"],"voices_note":"No weavers' accounts are published here yet. The UAE collection will add them only with consent and verification.","collaboration_notes":["Credit 'Al Sadu, UAE' — and the weavers — when using Sadu patterns.","Printed Sadu-style goods are not woven Sadu; say so.","UNESCO has flagged over-commercialisation as a risk; partner with safeguarding programmes rather than around them."],"editorial":{"lastReviewed":"2026-11-17","reviewedBy":"Culture Passport editorial desk (seed research)","notes":"Introductory passport for the UAE bridge collection, built only from UNESCO and government records.","openQuestions":["Weavers' own accounts, with consent.","Pattern names and their meanings.","Records for sadu traditions in neighbouring countries."]}}]$cp$::jsonb)
  on conflict do nothing;

insert into tradition_names ("id", "tradition_id", "kind", "name", "script", "lang", "note", "position")
  select "id", "tradition_id", "kind", "name", "script", "lang", "note", "position" from jsonb_populate_recordset(null::tradition_names, $cp$[{"id":"trad-kolhapuri:native:0","tradition_id":"trad-kolhapuri","kind":"native","name":"कोल्हापुरी चप्पल","script":"Devanagari","lang":"Marathi","note":null,"position":0},{"id":"trad-kolhapuri:native:1","tradition_id":"trad-kolhapuri","kind":"native","name":"ಕೊಲ್ಹಾಪುರಿ ಚಪ್ಪಲಿ","script":"Kannada","lang":"Kannada","note":null,"position":1},{"id":"trad-kolhapuri:alt:0","tradition_id":"trad-kolhapuri","kind":"alternate","name":"Kolhapuri","script":null,"lang":null,"note":null,"position":0},{"id":"trad-kolhapuri:alt:1","tradition_id":"trad-kolhapuri","kind":"alternate","name":"Kolhapuris","script":null,"lang":null,"note":null,"position":1},{"id":"trad-kolhapuri:alt:2","tradition_id":"trad-kolhapuri","kind":"alternate","name":"Kolhapuri sandal","script":null,"lang":null,"note":null,"position":2},{"id":"trad-kolhapuri:alt:3","tradition_id":"trad-kolhapuri","kind":"alternate","name":"Pie-taan / Paytaan (said to be an early name)","script":null,"lang":null,"note":null,"position":3},{"id":"trad-madhubani:native:0","tradition_id":"trad-madhubani","kind":"native","name":"मिथिला चित्रकला","script":"Devanagari","lang":"Maithili / Hindi","note":"Mithila painting","position":0},{"id":"trad-madhubani:native:1","tradition_id":"trad-madhubani","kind":"native","name":"मधुबनी पेंटिंग","script":"Devanagari","lang":"Hindi","note":null,"position":1},{"id":"trad-madhubani:alt:0","tradition_id":"trad-madhubani","kind":"alternate","name":"Mithila painting","script":null,"lang":null,"note":null,"position":0},{"id":"trad-madhubani:alt:1","tradition_id":"trad-madhubani","kind":"alternate","name":"Mithila art","script":null,"lang":null,"note":null,"position":1},{"id":"trad-madhubani:alt:2","tradition_id":"trad-madhubani","kind":"alternate","name":"Maithil painting","script":null,"lang":null,"note":null,"position":2},{"id":"trad-phulkari:native:0","tradition_id":"trad-phulkari","kind":"native","name":"ਫੁਲਕਾਰੀ","script":"Gurmukhi","lang":"Punjabi","note":null,"position":0},{"id":"trad-phulkari:native:1","tradition_id":"trad-phulkari","kind":"native","name":"پھلکاری","script":"Shahmukhi","lang":"Punjabi","note":null,"position":1},{"id":"trad-phulkari:alt:0","tradition_id":"trad-phulkari","kind":"alternate","name":"Bagh (fully covered phulkari)","script":null,"lang":null,"note":null,"position":0},{"id":"trad-phulkari:alt:1","tradition_id":"trad-phulkari","kind":"alternate","name":"Phulkari embroidery","script":null,"lang":null,"note":null,"position":1},{"id":"trad-warli:native:0","tradition_id":"trad-warli","kind":"native","name":"वारली चित्रकला","script":"Devanagari","lang":"Marathi","note":null,"position":0},{"id":"trad-warli:alt:0","tradition_id":"trad-warli","kind":"alternate","name":"Warli art","script":null,"lang":null,"note":null,"position":0},{"id":"trad-warli:alt:1","tradition_id":"trad-warli","kind":"alternate","name":"Varli painting","script":null,"lang":null,"note":null,"position":1},{"id":"trad-ajrakh:native:0","tradition_id":"trad-ajrakh","kind":"native","name":"અજરખ","script":"Gujarati","lang":"Gujarati / Kutchi","note":null,"position":0},{"id":"trad-ajrakh:native:1","tradition_id":"trad-ajrakh","kind":"native","name":"اجرڪ","script":"Arabic (Sindhi)","lang":"Sindhi","note":null,"position":1},{"id":"trad-ajrakh:alt:0","tradition_id":"trad-ajrakh","kind":"alternate","name":"Ajrak","script":null,"lang":null,"note":null,"position":0},{"id":"trad-ajrakh:alt:1","tradition_id":"trad-ajrakh","kind":"alternate","name":"Ajarakh","script":null,"lang":null,"note":null,"position":1},{"id":"trad-ajrakh:alt:2","tradition_id":"trad-ajrakh","kind":"alternate","name":"Kutch Ajrakh","script":null,"lang":null,"note":null,"position":2},{"id":"trad-sadu:native:0","tradition_id":"trad-sadu","kind":"native","name":"السدو","script":"Arabic","lang":"Arabic","note":null,"position":0},{"id":"trad-sadu:alt:0","tradition_id":"trad-sadu","kind":"alternate","name":"Sadu weaving","script":null,"lang":null,"note":null,"position":0},{"id":"trad-sadu:alt:1","tradition_id":"trad-sadu","kind":"alternate","name":"Al Sadu, traditional weaving skills in the United Arab Emirates","script":null,"lang":null,"note":null,"position":1}]$cp$::jsonb)
