  on conflict do nothing;

insert into tradition_places ("tradition_id", "place_id", "role", "note", "position")
  select "tradition_id", "place_id", "role", "note", "position" from jsonb_populate_recordset(null::tradition_places, $cp$[{"tradition_id":"trad-kolhapuri","place_id":"kolhapur","role":"gi-area","note":"Gives the chappal its name","position":0},{"tradition_id":"trad-kolhapuri","place_id":"sangli","role":"gi-area","note":null,"position":1},{"tradition_id":"trad-kolhapuri","place_id":"satara","role":"gi-area","note":null,"position":2},{"tradition_id":"trad-kolhapuri","place_id":"solapur","role":"gi-area","note":null,"position":3},{"tradition_id":"trad-kolhapuri","place_id":"belagavi","role":"gi-area","note":null,"position":4},{"tradition_id":"trad-kolhapuri","place_id":"dharwad","role":"gi-area","note":null,"position":5},{"tradition_id":"trad-kolhapuri","place_id":"bagalkot","role":"gi-area","note":null,"position":6},{"tradition_id":"trad-kolhapuri","place_id":"vijayapura","role":"gi-area","note":null,"position":7},{"tradition_id":"trad-madhubani","place_id":"madhubani","role":"gi-area","note":"District that gives the painting its best-known name","position":0},{"tradition_id":"trad-madhubani","place_id":"darbhanga","role":"shared","note":"Mithila region, Bihar","position":1},{"tradition_id":"trad-madhubani","place_id":"janakpur","role":"shared","note":"Mithila region, Nepal","position":2},{"tradition_id":"trad-phulkari","place_id":"patiala","role":"shared","note":"Punjab, India","position":0},{"tradition_id":"trad-phulkari","place_id":"amritsar","role":"shared","note":"Punjab, India","position":1},{"tradition_id":"trad-phulkari","place_id":"lahore","role":"shared","note":"Punjab, Pakistan","position":2},{"tradition_id":"trad-phulkari","place_id":"haryana","role":"gi-area","note":null,"position":3},{"tradition_id":"trad-phulkari","place_id":"rajasthan-north","role":"gi-area","note":null,"position":4},{"tradition_id":"trad-warli","place_id":"dahanu","role":"community-home","note":null,"position":0},{"tradition_id":"trad-warli","place_id":"palghar","role":"community-home","note":null,"position":1},{"tradition_id":"trad-warli","place_id":"dnh","role":"gi-area","note":null,"position":2},{"tradition_id":"trad-ajrakh","place_id":"sindh","role":"shared","note":"Sindh, Pakistan","position":0},{"tradition_id":"trad-ajrakh","place_id":"kutch","role":"gi-area","note":"Kutch, Gujarat","position":1},{"tradition_id":"trad-ajrakh","place_id":"ajrakhpur","role":"production","note":null,"position":2},{"tradition_id":"trad-ajrakh","place_id":"dhamadka","role":"historic-centre","note":null,"position":3},{"tradition_id":"trad-ajrakh","place_id":"barmer","role":"shared","note":"Rajasthan","position":4},{"tradition_id":"trad-sadu","place_id":"al-ain","role":"community-home","note":"Rural communities of the UAE","position":0},{"tradition_id":"trad-sadu","place_id":"abu-dhabi","role":"community-home","note":null,"position":1}]$cp$::jsonb)
  on conflict do nothing;

insert into tradition_communities ("tradition_id", "community_id", "role", "position")
  select "tradition_id", "community_id", "role", "position" from jsonb_populate_recordset(null::tradition_communities, $cp$[{"tradition_id":"trad-kolhapuri","community_id":"charmakar","role":"Makers, historically and today","position":0},{"tradition_id":"trad-madhubani","community_id":"mithila-women","role":"Painters, historically and today","position":0},{"tradition_id":"trad-phulkari","community_id":"punjabi-women","role":"Embroiderers","position":0},{"tradition_id":"trad-warli","community_id":"warli","role":"Painters and custodians","position":0},{"tradition_id":"trad-ajrakh","community_id":"khatri","role":"Dyers and block-printers","position":0},{"tradition_id":"trad-sadu","community_id":"bedouin-women-uae","role":"Spinners, dyers and weavers","position":0}]$cp$::jsonb)
  on conflict do nothing;

insert into tradition_sections ("tradition_id", "chapter", "locale", "blocks")
  select "tradition_id", "chapter", "locale", "blocks" from jsonb_populate_recordset(null::tradition_sections, $cp$[{"tradition_id":"trad-kolhapuri","chapter":"origins","locale":"en","blocks":[{"type":"p","text":"The chappal takes its name from Kolhapur, in southern Maharashtra, but it has never belonged to one town. The geographical indication registered for it covers eight districts: Kolhapur, Sangli, Satara and Solapur in Maharashtra, and Belagavi, Dharwad, Bagalkot and Vijayapura in Karnataka.","claims":["kol-gi-area"]},{"type":"p","text":"How old is it? Popular histories place its beginnings in the 12th–13th centuries, before it was called 'Kolhapuri' at all. Other accounts credit a single family with designing it in 1920. We have found no primary evidence for either date, so we show both — and mark them disputed.","claims":["kol-origin-date"]},{"type":"p","text":"Early forms are said to have gone by village names — Kapashi, Paytaan, Kachkadi, Bakkalnali, Pukri. These names survive in oral and journalistic accounts rather than in archives, and we record them as such.","claims":["kol-early-names"]},{"type":"p","text":"The trade is widely said to have flourished under royal patronage in princely Kolhapur. Accounts disagree on which ruler and when; most point to Chhatrapati Shahu Maharaj in the early 20th century, with tanning centres opened under his rule.","claims":["kol-shahu"]},{"type":"figure","media":"kolhapur-shop-1"},{"type":"note","title":"On names and ownership","text":"A geographical indication protects the use of a name — 'Kolhapuri Chappal' — for goods made in the registered area. It records a place-based reputation. It is not a patent, and it does not make anyone the worldwide owner of the open-toed sandal as a form.","claims":["kol-gi-dates","kol-gi-proprietors"]}]},{"tradition_id":"trad-kolhapuri","chapter":"significance","locale":"en","blocks":[{"type":"p","text":"The chappal is valued for being made to last and made by hand: leather and thread, no nails, a form refined for heat and dust. Its name carries the reputation of a region; its price, at a roadside stall, has often been a few hundred rupees.","claims":["kol-materials","kol-price-gap"]},{"type":"pull","text":"The design travelled in seconds. The name, the place and the makers took a week of public argument to catch up.","attribution":"Culture Passport editorial"}]},{"tradition_id":"trad-kolhapuri","chapter":"makers","locale":"en","blocks":[{"type":"p","text":"Kolhapuri chappals are predominantly made — then and now — by Charmakar leather-working communities. The craft runs through tanning, cutting, braiding and stitching, often divided between households and workshops.","claims":["kol-makers"]},{"type":"p","text":"The material story is changing. Leather was traditionally vegetable-tanned in and around Kolhapur; reporting in 2025 found that many local tanneries had closed and makers now buy leather from elsewhere, often chemically tanned.","claims":["kol-tanning"]}]},{"tradition_id":"trad-kolhapuri","chapter":"travels","locale":"en","blocks":[{"type":"p","text":"Inspiration is not the problem. Footwear has always borrowed across borders, and a sandal can be admired in Milan as easily as in Kolhapur. What this chapter documents is narrower: the moment when a recognisable design travelled and its name, place and makers did not."}]},{"tradition_id":"trad-madhubani","chapter":"origins","locale":"en","blocks":[{"type":"p","text":"Madhubani is a district; Mithila is a region. The painting carries both names, and the region it comes from spans northern Bihar in India and the adjoining Madhesh of Nepal, around Janakpur. This passport is listed under both countries for that reason.","claims":["mad-region"]},{"type":"p","text":"It was painted by women, on the walls and floors of homes, for rituals and especially weddings. A widely told story traces it to the Ramayana — to King Janaka asking for his palace to be painted for the wedding of his daughter Sita. We record that as tradition, not history.","claims":["mad-walls","mad-legend"]},{"type":"p","text":"Outsiders' accounts begin with disaster. After the 1934 Bihar–Nepal earthquake, the British officer William G. Archer saw paintings exposed on the inner walls of damaged houses; he returned to photograph them and published an article in the journal Marg in 1949.","claims":["mad-archer"]},{"type":"note","title":"Whose story was told first?","text":"Scholars note that Archer's framing centred Brahmin and Kayastha painting and overlooked other communities' traditions. A history that begins with the person who 'discovered' an art form is one of the gaps this archive exists to close.","claims":["mad-archer-critique"]},{"type":"figure","media":"madhubani-artist"},{"type":"p","text":"In the drought of the mid-1960s, the All India Handicrafts Board — under Pupul Jayakar, with the artist-officer Bhaskar Kulkarni — encouraged women to paint on paper so their work could be sold. Wall painting became portable, and Mithila painters began to be known by name.","claims":["mad-paper"]}]},{"tradition_id":"trad-madhubani","chapter":"significance","locale":"en","blocks":[{"type":"p","text":"Commonly described styles include bharni (filled colour), kachni (fine line), tantrik, godna and kohbar — the last named for the painted wedding chamber. These are classifications used by practitioners and scholars, and the boundaries between them are not fixed.","claims":["mad-styles"]},{"type":"pull","text":"The painting left the wall in the 1960s. The painters' names took decades to follow.","attribution":"Culture Passport editorial"}]},{"tradition_id":"trad-madhubani","chapter":"makers","locale":"en","blocks":[{"type":"p","text":"Mithila painting has been a women's art, and its best-known practitioners — honoured nationally since the 1970s — are women. The Padma Shri, one of India's highest civilian honours, has gone to Jagdamba Devi, Sita Devi, Ganga Devi, Mahasundari Devi, Baua Devi and Dulari Devi, among others.","claims":["mad-padma"]}]},{"tradition_id":"trad-madhubani","chapter":"travels","locale":"en","blocks":[{"type":"p","text":"Few Indian painting traditions have travelled further: to Delhi's craft markets, to Japanese museum walls, to railway stations and printed merchandise. The question here is not whether it should travel, but whether the women who made it travel with it."}]},{"tradition_id":"trad-phulkari","chapter":"origins","locale":"en","blocks":[{"type":"p","text":"Phulkari belongs to Punjab — a region now divided between India and Pakistan. It was made on both sides of today's border, which is why this passport is filed under India but listed under Pakistan too.","claims":["phk-region"]},{"type":"p","text":"How old is it? Sources disagree, and we have not found reliable dating for its beginnings. What is well documented is how it was made and used by the late 19th and early 20th centuries.","claims":["phk-dating"]},{"type":"figure","media":"phulkari-patiala-1900"},{"type":"p","text":"Partition in 1947 divided Punjab and scattered the households, neighbours and merchants — sellers of hand-woven khaddar and silk floss — on whom the embroidery depended.","claims":["phk-partition"]}]},{"tradition_id":"trad-phulkari","chapter":"significance","locale":"en","blocks":[{"type":"p","text":"Phulkari and bagh were made for family and ceremony, above all weddings. Some pieces were embroidered for a bride and carried with her into a new household.","claims":["phk-ceremony"]}]},{"tradition_id":"trad-phulkari","chapter":"makers","locale":"en","blocks":[{"type":"p","text":"Phulkari is women's work, made at home and often together. Its technique turns the cloth into a counting grid: stitches are darned on the reverse, following the weave of the khaddar, so the pattern is built thread by thread.","claims":["phk-technique"]}]},{"tradition_id":"trad-phulkari","chapter":"travels","locale":"en","blocks":[{"type":"p","text":"Phulkari has travelled into museums and into fashion, often at the same time. Its story is also one of a border: an embroidery that belongs to a region now split between two countries."}]},{"tradition_id":"trad-warli","chapter":"origins","locale":"en","blocks":[{"type":"p","text":"Warli painting is the wall painting of the Warli (Varli) people, an Adivasi community of the coastal and hill districts along the Maharashtra–Gujarat border. Its registered geographical area spans Maharashtra, Gujarat, Dadra & Nagar Haveli and Daman & Diu.","claims":["wrl-community","wrl-gi"]},{"type":"p","text":"Accounts describe white paint of rice flour and water on mud walls, often over red ochre or cow dung, and a vocabulary of circles, triangles, squares and lines. This draft has not yet been reviewed with Warli painters, so these descriptions are marked for verification.","claims":["wrl-materials"]},{"type":"figure","media":"warli-mashe"}]},{"tradition_id":"trad-warli","chapter":"significance","locale":"en","blocks":[{"type":"p","text":"Ritual meaning, the names of motifs and who may paint what are questions this passport will answer only with the community. Until then, we describe what is publicly documented and leave the rest open."}]},{"tradition_id":"trad-warli","chapter":"makers","locale":"en","blocks":[{"type":"p","text":"The best-documented Warli painter is Jivya Soma Mashe, who took the painting onto paper and canvas and exhibited internationally. He received the Padma Shri in 2011 and died in Dahanu in 2018.","claims":["wrl-mashe"]}]},{"tradition_id":"trad-warli","chapter":"travels","locale":"en","blocks":[{"type":"p","text":"Warli's simple geometry makes it easy to copy, and it is copied everywhere. Reporting suggests that this — images circulating online without context — is part of why a community organisation went to the trouble of registering it.","claims":["wrl-gi-motive"]}]},{"tradition_id":"trad-ajrakh","chapter":"origins","locale":"en","blocks":[{"type":"p","text":"Ajrakh is shared. It is made and worn in Sindh, in Pakistan, and printed in Kutch in Gujarat and in Barmer in Rajasthan. The geographical indication registered in India in 2024 covers Kutch Ajrakh only; it says nothing about ajrak from Sindh.","claims":["ajk-shared","ajk-gi"]},{"type":"p","text":"It is associated with Khatri dyer-printer families. Popular histories say they came to Kutch from Sindh; accounts of when differ, from the 16th century to about 400 years ago.","claims":["ajk-khatri","ajk-migration"]},{"type":"note","title":"Similarity is not ancestry","text":"Ajrakh is often called '5,000 years old', linking it to the trefoil-patterned robe of the Mohenjo-daro 'priest-king' sculpture. That link rests on visual similarity alone. No textile evidence connects the two, and this archive does not present resemblance as proof of descent.","claims":["ajk-indus"]},{"type":"p","text":"Even the name is contested: printers explain it as 'aaj rakh' — keep it today — while others connect it to the Arabic azraq, blue.","claims":["ajk-name"]}]},{"tradition_id":"trad-ajrakh","chapter":"significance","locale":"en","blocks":[]},{"tradition_id":"trad-ajrakh","chapter":"makers","locale":"en","blocks":[{"type":"p","text":"After the 2001 Kutch earthquake, many printing families moved from Dhamadka to a new settlement near Bhuj — Ajrakhpur — which now holds the registered proprietor of the GI.","claims":["ajk-2001"]},{"type":"p","text":"An oral-history interview with master printer Dr Ismail Mohammad Khatri, recorded for the University of Warwick, is the best first-person account we can point to. We link to it rather than paraphrase him."}]},{"tradition_id":"trad-ajrakh","chapter":"travels","locale":"en","blocks":[{"type":"p","text":"Ajrakh's patterns now appear in fashion far from Kutch and Sindh, both hand-printed and digitally imitated. Reporting from Kutch describes how rising demand is changing the craft's economics.","claims":["ajk-demand"]}]},{"tradition_id":"trad-sadu","chapter":"origins","locale":"en","blocks":[{"type":"p","text":"UNESCO describes Al Sadu as a traditional form of weaving practised by Bedouin women in rural communities of the United Arab Emirates. Men shear the sheep, camels and goats; women clean and prepare the wool, spin it, dye it and weave it.","claims":["sadu-what","sadu-fibres"]},{"type":"p","text":"Its colours are black, white, brown, beige and red, in narrow bands of geometric design. Woven pieces furnish homes and tents and dress camels and horses.","claims":["sadu-colours","sadu-uses"]}]},{"tradition_id":"trad-sadu","chapter":"significance","locale":"en","blocks":[{"type":"p","text":"Weaving was also a social occasion. Gatherings of weavers are the traditional means of passing the skill on: girls learn by watching, then by sorting wool, before they are trusted with the loom.","claims":["sadu-transmission"]}]},{"tradition_id":"trad-sadu","chapter":"makers","locale":"en","blocks":[{"type":"p","text":"In 2011 UNESCO judged the skill to be at risk — its know-how kept by a dwindling number of older women. Fourteen years of safeguarding later, it was moved to the Representative List and the UAE's programme was selected as a good practice for others to learn from.","claims":["sadu-2011","sadu-2025"]}]},{"tradition_id":"trad-sadu","chapter":"travels","locale":"en","blocks":[{"type":"p","text":"UNESCO itself has warned about over-commercialisation: Sadu patterns are now printed on goods far from the loom. As the UAE collection grows, this chapter will document how those patterns travel.","claims":["sadu-2020"]}]}]$cp$::jsonb)
  on conflict do nothing;

insert into tradition_translations ("tradition_id", "locale", "name", "tagline", "summary", "reviewed")
  select "tradition_id", "locale", "name", "tagline", "summary", "reviewed" from jsonb_populate_recordset(null::tradition_translations, $cp$[{"tradition_id":"trad-kolhapuri","locale":"mr","name":"कोल्हापुरी चप्पल","tagline":null,"summary":null,"reviewed":false}]$cp$::jsonb)
  on conflict do nothing;

insert into claims ("id", "tradition_id", "text", "level", "note", "position")
  select "id", "tradition_id", "text", "level", "note", "position" from jsonb_populate_recordset(null::claims, $cp$[{"id":"kol-gi-area","tradition_id":"trad-kolhapuri","text":"The Kolhapuri Chappal geographical indication covers Kolhapur, Sangli, Satara and Solapur districts in Maharashtra and Belagavi, Dharwad, Bagalkot and Vijayapura (Bijapur) districts in Karnataka.","level":"documented","note":null,"position":0},{"id":"kol-gi-dates","tradition_id":"trad-kolhapuri","text":"The GI application (No. 169) was filed on 4 May 2009; the registry records certificate No. 329 dated 11 December 2018. The registration was widely reported in mid-2019.","level":"documented","note":"Some sources give 4 April 2009 as the filing date; several date the grant to June–July 2019, when it was publicised.","position":1},{"id":"kol-gi-proprietors","tradition_id":"trad-kolhapuri","text":"Court reporting identifies LIDCOM (Maharashtra) and LIDKAR (Karnataka) as the registered proprietors of the GI; the registry's public record names the Central Leather Research Institute as applicant.","level":"documented","note":"The two records are not necessarily in conflict (an institution may file for proprietors), but we have not seen the certificate itself.","position":2},{"id":"kol-origin-date","tradition_id":"trad-kolhapuri","text":"The chappal's origins are often placed in the 12th–13th centuries; another account attributes its design to the Saudagar family in 1920.","level":"disputed","note":"Neither date is supported by a primary source we could find. Open presents the early date as belief; Wikipedia's 1920 claim is uncited.","position":3},{"id":"kol-early-names","tradition_id":"trad-kolhapuri","text":"Early forms are said to have been known as Kapashi, Paytaan, Kachkadi, Bakkalnali and Pukri, after the villages where they were made.","level":"community","note":"Reported as tradition ('is said to'); meanings of the names are not recorded in our sources.","position":4},{"id":"kol-shahu","tradition_id":"trad-kolhapuri","text":"Accounts credit the rulers of Kolhapur with encouraging the trade: Wikipedia names Shahu I and his successor Rajaram II and counts 29 tanning centres opened in Shahu's reign; Open Magazine places Shahu Maharaj's patronage in the early 20th century.","level":"interpretation","note":"Wikipedia links this to 'Shahu I' and successors and cites 29 tanning centres from 2019 newspaper features; Open places patronage in the early 20th century. Which ruler, and when, needs archival confirmation.","position":5},{"id":"kol-makers","tradition_id":"trad-kolhapuri","text":"Kolhapuri chappals are predominantly made by Charmakar leather-working communities.","level":"documented","note":"Other community names appear in commercial sources but are not yet verified. Community self-identification will be recorded in consultation with makers.","position":6},{"id":"kol-materials","tradition_id":"trad-kolhapuri","text":"Kolhapuri chappals are traditionally made from buffalo hide and thread, hand-stitched without nails.","level":"documented","note":null,"position":7},{"id":"kol-tanning","tradition_id":"trad-kolhapuri","text":"Kolhapuri leather was known for local vegetable tanning; by 2025 most tanneries in the city had shut after a crackdown on effluents, and makers relied mainly on tanneries in Tamil Nadu that use chemical processes.","level":"documented","note":"Wikipedia still describes local vegetable tanning; Open's 2025 reporting is more recent.","position":8},{"id":"kol-price-gap","tradition_id":"trad-kolhapuri","text":"Press coverage set a pair bargained for about ₹400 at a Delhi market against Prada's sandal at about ₹1 lakh; Prada's 2026 made-in-India edition was reported at about €750 (roughly ₹83,000).","level":"documented","note":null,"position":9},{"id":"mad-region","tradition_id":"trad-madhubani","text":"Madhubani (Mithila) painting comes from the Mithila region, which spans northern Bihar in India and adjoining parts of Nepal.","level":"documented","note":null,"position":0},{"id":"mad-walls","tradition_id":"trad-madhubani","text":"It was traditionally painted by women on the walls and floors of homes, especially for rituals and weddings.","level":"documented","note":null,"position":1},{"id":"mad-legend","tradition_id":"trad-madhubani","text":"A widely told origin story links the painting to King Janaka commissioning paintings for the wedding of his daughter Sita.","level":"community","note":"An origin legend, recorded as tradition.","position":2},{"id":"mad-archer","tradition_id":"trad-madhubani","text":"After the 1934 Bihar–Nepal earthquake, William G. Archer saw paintings on the inner walls of damaged houses, later photographed them, and published an article in Marg in 1949.","level":"documented","note":null,"position":3},{"id":"mad-archer-critique","tradition_id":"trad-madhubani","text":"Archer's framing centred Brahmin and Kayastha styles and overlooked other communities' painting.","level":"interpretation","note":null,"position":4},{"id":"mad-paper","tradition_id":"trad-madhubani","text":"During the drought of the mid-1960s the All India Handicrafts Board (called the Handloom Board in some accounts), under Pupul Jayakar and with Bhaskar Kulkarni, encouraged women to paint on paper for sale.","level":"documented","note":"Sources differ on whether the intervention began in 1964 or 1966–68.","position":5},{"id":"mad-styles","tradition_id":"trad-madhubani","text":"Commonly named styles include bharni, kachni, tantrik, godna and kohbar.","level":"interpretation","note":null,"position":6},{"id":"mad-padma","tradition_id":"trad-madhubani","text":"Mithila painters who have received the Padma Shri include Jagdamba Devi (1975), Sita Devi (1981), Ganga Devi (1984), Mahasundari Devi (2011), Baua Devi (2017), Godawari Dutta (2019) and Dulari Devi (2021).","level":"documented","note":"One outlet gives 2010 for Mahasundari Devi, and Wikipedia gives 2020 for Dulari Devi; the 2021 Padma list (announced 25 January 2021) names her.","position":7},{"id":"mad-gi","tradition_id":"trad-madhubani","text":"'Madhubani Paintings' was registered as a geographical indication for Bihar (certificate dated 16 May 2007) on an application by Bihar's Director of Industries.","level":"documented","note":"The record shows validity to 21 August 2025 and a 2024 renewal notice; current renewal status is not confirmed.","position":8},{"id":"mad-museum","tradition_id":"trad-madhubani","text":"The Mithila Museum in Tokamachi, Niigata, Japan, was founded by Tokio Hasegawa and inaugurated in 1982; Hasegawa had converted an elementary school there into a centre for the collection.","level":"documented","note":"Reported collection sizes vary from about 850 to over 3,000 works.","position":9},{"id":"phk-region","tradition_id":"trad-phulkari","text":"Phulkari is an embroidery tradition of Punjab, a region now divided between India and Pakistan.","level":"documented","note":null,"position":0},{"id":"phk-dating","tradition_id":"trad-phulkari","text":"The date of phulkari's origin is not established.","level":"unverified","note":"Secondary sources variously cite medieval or 15th-century origins; we found no reliable evidence for either.","position":1},{"id":"phk-technique","tradition_id":"trad-phulkari","text":"Phulkari is worked in untwisted silk floss (pat) on hand-woven cotton (khaddar), mainly in darning stitch from the reverse of the cloth.","level":"documented","note":null,"position":2},{"id":"phk-ceremony","tradition_id":"trad-phulkari","text":"Phulkari and bagh were made for family and ceremonial use, especially weddings.","level":"documented","note":null,"position":3},{"id":"phk-partition","tradition_id":"trad-phulkari","text":"The 1947 Partition disrupted the communities and trade networks that sustained phulkari.","level":"interpretation","note":null,"position":4},{"id":"phk-gi","tradition_id":"trad-phulkari","text":"Phulkari was registered as a GI for Punjab, Haryana and Rajasthan (certificate dated 22 October 2010) on an application by the Punjab Small Industries & Export Corporation.","level":"documented","note":"Many secondary sources give 2011.","position":5},{"id":"wrl-community","tradition_id":"trad-warli","text":"Warli painting is the wall painting of the Warli Adivasi community, centred on Dahanu, Talasari, Jawhar, Palghar and Mokhada in northern Maharashtra; the GI also covers Gujarat, Dadra & Nagar Haveli and Daman & Diu.","level":"documented","note":null,"position":0},{"id":"wrl-materials","tradition_id":"trad-warli","text":"Warli painting is traditionally made in white paint of rice flour and water on mud walls, often over red ochre (geru) or cow dung, using circles, triangles, squares and lines.","level":"unverified","note":"To be reviewed with Warli painters before it is marked documented.","position":1},{"id":"wrl-mashe","tradition_id":"trad-warli","text":"Jivya Soma Mashe exhibited at 'Magiciens de la Terre' (Centre Pompidou, 1989), received the Padma Shri in 2011, and died in Dahanu on 15 May 2018.","level":"documented","note":null,"position":2},{"id":"wrl-gi","tradition_id":"trad-warli","text":"The Warli Painting GI (certificate dated 31 March 2014) is registered to Adivasi Yuva Seva Sangh (AYUSH), based in Dahanu, for Maharashtra, Gujarat, Dadra & Nagar Haveli and Daman & Diu.","level":"documented","note":"Filing date displays as 06-07-2011 in the registry; other sources give 7 June 2011.","position":3},{"id":"wrl-gi-motive","tradition_id":"trad-warli","text":"AYUSH is reported to have pursued the GI after its online use of Warli images was challenged (by Orkut, per The Better India; by European galleries, per SabrangIndia); The Better India reports members spent over ₹5 lakh of their own money.","level":"community","note":null,"position":4},{"id":"ajk-shared","tradition_id":"trad-ajrakh","text":"Ajrakh is a resist-printed, naturally dyed textile shared by Sindh (Pakistan) and Kutch and Barmer (India).","level":"documented","note":null,"position":0},{"id":"ajk-khatri","tradition_id":"trad-ajrakh","text":"Ajrakh is associated with Khatri dyer-printer families, many of whom trace their origins to Sindh.","level":"community","note":null,"position":1},{"id":"ajk-migration","tradition_id":"trad-ajrakh","text":"Accounts of when Khatri printers settled in Kutch differ: a popular history says they came from Sindh about 400 years ago, while a family oral history places the first settler in Dhamadka in the 16th century.","level":"disputed","note":"Accounts differ on the date and on the reasons for the move.","position":2},{"id":"ajk-name","tradition_id":"trad-ajrakh","text":"The name is explained as 'aaj rakh' ('keep it today') or linked to the Arabic azraq ('blue').","level":"disputed","note":"Both are folk or popular etymologies; neither is established.","position":3},{"id":"ajk-indus","tradition_id":"trad-ajrakh","text":"Some historians link ajrakh to the trefoil-patterned robe of Mohenjo-daro's 'priest-king' sculpture; no cloth survives to show a direct line.","level":"disputed","note":"A popular claim based on visual similarity. Culture Passport does not treat resemblance as evidence of historical continuity.","position":4},{"id":"ajk-2001","tradition_id":"trad-ajrakh","text":"After the 2001 Kutch earthquake, many printing families moved from Dhamadka to Ajrakhpur, near Bhuj.","level":"documented","note":"Sources also cite rising iron content in Dhamadka's water.","position":5},{"id":"ajk-gi","tradition_id":"trad-ajrakh","text":"'Kutch Ajrakh Print of Gujarat' was registered as a GI on an application by Ajarakhpur Hastkala Vikas Sangathan filed on 31 January 2023, with the certificate issued in April 2024.","level":"documented","note":null,"position":6},{"id":"ajk-demand","tradition_id":"trad-ajrakh","text":"Rising demand has changed the dynamics of the craft in Kutch.","level":"interpretation","note":null,"position":7},{"id":"sadu-what","tradition_id":"trad-sadu","text":"Al Sadu is a traditional weaving practised by Bedouin women in rural communities of the UAE.","level":"documented","note":null,"position":0},{"id":"sadu-fibres","tradition_id":"trad-sadu","text":"Men shear sheep, camels and goats; women clean and prepare the wool, spin it on a drop spindle, dye it and weave it on a floor loom in a warp-faced plain weave.","level":"documented","note":null,"position":1},{"id":"sadu-colours","tradition_id":"trad-sadu","text":"Traditional colours are black, white, brown, beige and red, in narrow bands of geometric design.","level":"documented","note":null,"position":2},{"id":"sadu-uses","tradition_id":"trad-sadu","text":"Al Sadu is used for soft furnishings and for decorative accessories for camels and horses.","level":"documented","note":null,"position":3},{"id":"sadu-transmission","tradition_id":"trad-sadu","text":"Girls learn by watching and by tasks such as sorting wool; gatherings of weavers are the traditional means of transmission.","level":"documented","note":null,"position":4},{"id":"sadu-2011","tradition_id":"trad-sadu","text":"UNESCO inscribed Al Sadu on the Urgent Safeguarding List in 2011.","level":"documented","note":null,"position":5},{"id":"sadu-2020","tradition_id":"trad-sadu","text":"In 2020 UNESCO invited the UAE to integrate Al Sadu into school teaching, address access to raw materials and natural dyeing, and heed the risk of over-commercialisation.","level":"documented","note":null,"position":6},{"id":"sadu-2025","tradition_id":"trad-sadu","text":"In December 2025, in New Delhi, UNESCO transferred Al Sadu to the Representative List and selected the UAE's safeguarding programme for the Register of Good Safeguarding Practices.","level":"documented","note":"Some Abu Dhabi heritage pages still describe the earlier listing.","position":7}]$cp$::jsonb)
  on conflict do nothing;

