graphy","position":0},{"claim_id":"mad-paper","source_id":"fap-context","position":0},{"claim_id":"mad-paper","source_id":"tbi-archer","position":1},{"claim_id":"mad-styles","source_id":"wiki-madhubani","position":0},{"claim_id":"mad-padma","source_id":"astaguru-women-artists","position":0},{"claim_id":"mad-padma","source_id":"wiki-madhubani","position":1},{"claim_id":"mad-padma","source_id":"padma-2021","position":2},{"claim_id":"mad-gi","source_id":"gi-37","position":0},{"claim_id":"mad-museum","source_id":"fap-hasegawa","position":0},{"claim_id":"mad-museum","source_id":"indica-hasegawa","position":1},{"claim_id":"phk-region","source_id":"pma-phulkari-2017","position":0},{"claim_id":"phk-region","source_id":"dch-phulkari","position":1},{"claim_id":"phk-dating","source_id":"dch-phulkari","position":0},{"claim_id":"phk-technique","source_id":"dch-phulkari","position":0},{"claim_id":"phk-technique","source_id":"pma-phulkari-2017","position":1},{"claim_id":"phk-technique","source_id":"scroll-phulkari-partition","position":2},{"claim_id":"phk-ceremony","source_id":"dch-phulkari","position":0},{"claim_id":"phk-ceremony","source_id":"pma-phulkari-2017","position":1},{"claim_id":"phk-partition","source_id":"scroll-phulkari-partition","position":0},{"claim_id":"phk-partition","source_id":"pma-phulkari-2017","position":1},{"claim_id":"phk-gi","source_id":"gi-27","position":0},{"claim_id":"wrl-community","source_id":"gi-239","position":0},{"claim_id":"wrl-community","source_id":"wiki-warli","position":1},{"claim_id":"wrl-materials","source_id":"wiki-warli","position":0},{"claim_id":"wrl-materials","source_id":"tbi-warli-ayush","position":1},{"claim_id":"wrl-mashe","source_id":"wiki-mashe","position":0},{"claim_id":"wrl-gi","source_id":"gi-239","position":0},{"claim_id":"wrl-gi","source_id":"dna-warli-gi","position":1},{"claim_id":"wrl-gi-motive","source_id":"tbi-warli-ayush","position":0},{"claim_id":"wrl-gi-motive","source_id":"sabrang-warli","position":1},{"claim_id":"ajk-shared","source_id":"lhi-ajrakh","position":0},{"claim_id":"ajk-shared","source_id":"khamir-ajrakh","position":1},{"claim_id":"ajk-shared","source_id":"gi-1050","position":2},{"claim_id":"ajk-khatri","source_id":"warwick-khatri","position":0},{"claim_id":"ajk-khatri","source_id":"lhi-ajrakh","position":1},{"claim_id":"ajk-migration","source_id":"lhi-ajrakh","position":0},{"claim_id":"ajk-migration","source_id":"warwick-khatri","position":1},{"claim_id":"ajk-name","source_id":"lhi-ajrakh","position":0},{"claim_id":"ajk-indus","source_id":"lhi-ajrakh","position":0},{"claim_id":"ajk-indus","source_id":"gs-ajrakh-5000","position":1},{"claim_id":"ajk-2001","source_id":"wire-ajrakh","position":0},{"claim_id":"ajk-2001","source_id":"lhi-ajrakh","position":1},{"claim_id":"ajk-gi","source_id":"gi-1050","position":0},{"claim_id":"ajk-gi","source_id":"ot-ajrakh-gi","position":1},{"claim_id":"ajk-demand","source_id":"wire-ajrakh","position":0},{"claim_id":"sadu-what","source_id":"unesco-20com-sadu","position":0},{"claim_id":"sadu-fibres","source_id":"unesco-20com-sadu","position":0},{"claim_id":"sadu-colours","source_id":"unesco-20com-sadu","position":0},{"claim_id":"sadu-uses","source_id":"unesco-20com-sadu","position":0},{"claim_id":"sadu-transmission","source_id":"unesco-20com-sadu","position":0},{"claim_id":"sadu-2011","source_id":"unesco-20com-sadu","position":0},{"claim_id":"sadu-2011","source_id":"unesco-15com-sadu","position":1},{"claim_id":"sadu-2020","source_id":"unesco-15com-sadu","position":0},{"claim_id":"sadu-2025","source_id":"unesco-20com-sadu","position":0},{"claim_id":"sadu-2025","source_id":"national-ahalla-2025","position":1}]$cp$::jsonb)
