insert into case_studies ("id", "tradition_id", "slug", "code", "title", "kind", "parties", "summary", "status", "travelled", "left_behind", "legal_note", "comparison", "open_questions", "position")
  select "id", "tradition_id", "slug", "code", "title", "kind", "parties", "summary", "status", "travelled", "left_behind", "legal_note", "comparison", "open_questions", "position" from jsonb_populate_recordset(null::case_studies, $cp$[{"id":"case-kolhapuri-prada","tradition_id":"trad-kolhapuri","slug":"prada-2025","code":"001-A","title":"The runway, Milan, June 2025","kind":"acknowledged-inspiration","parties":["Prada","MACCIA","LIDCOM","LIDKAR","Kolhapuri chappal makers"],"summary":"Open-toed leather sandals in Prada's Men's Spring/Summer 2026 show were widely recognised as Kolhapuri in style, but presented as 'leather sandals'. After public criticism Prada acknowledged the Indian inspiration, visited Kolhapur, signed an agreement with the GI proprietors and, in 2026, released a collection made in India.","status":"Inspiration acknowledged (June 2025) · Collaboration launched (2026)","travelled":["The open-toed, flat leather silhouette","The toe loop and T-strap arrangement","The braided leather band across the foot","The warm, tan leather finish"],"left_behind":["The name 'Kolhapuri'","Eight districts across two states","Charmakar makers and their workshops","A registered geographical indication","The difference between a roadside price and a runway price"],"legal_note":"No court has ruled that Prada infringed the geographical indication. The Bombay High Court dismissed a public interest litigation because the petitioners were not the registered proprietors; it left LIDCOM and LIDKAR free to act. A GI protects the use of a name for goods from a registered area — it does not by itself grant worldwide rights over a sandal design.","comparison":{"traditional":{"title":"Kolhapur chappal, late 20th century","media":"bata-chappal-445","points":["Toe loop","Braided band","Flat leather sole","Hand-stitched, no nails"]},"adaptation":{"title":"Runway interpretation, June 2025","points":["Open-toed flat sandal","Leather upper","Described as 'leather sandals'","No reference to India in show notes"],"mediaNote":"We have not licensed runway photography, so we will not reproduce it. Editors can attach a properly licensed image from the admin. Until then, see the photo galleries in the linked press coverage."}},"open_questions":["How are proceeds or training places distributed among makers outside the LIDCOM and LIDKAR networks?","Will future collections credit the tradition by name at the moment of first presentation?","Do makers themselves consider the outcome adequate? We have not yet asked them directly."],"position":0}]$cp$::jsonb)
  on conflict do nothing;

