  on conflict do nothing;

insert into case_questions ("id", "case_id", "q", "a", "level", "position")
  select "id", "case_id", "q", "a", "level", "position" from jsonb_populate_recordset(null::case_questions, $cp$[{"id":"case-kolhapuri-prada:q0","case_id":"case-kolhapuri-prada","q":"What design elements travelled?","a":"An open-toed, flat leather sandal with a toe loop and braided upper — the features observers in India and abroad immediately read as Kolhapuri.","level":"documented","position":0},{"id":"case-kolhapuri-prada:q1","case_id":"case-kolhapuri-prada","q":"What was the traditional cultural context?","a":"Hand-stitched footwear made predominantly by Charmakar leather-workers in four districts of Maharashtra and four of Karnataka, protected as a geographical indication since 2018–19.","level":"documented","position":1},{"id":"case-kolhapuri-prada:q2","case_id":"case-kolhapuri-prada","q":"How was the design described commercially?","a":"As 'leather sandals'. The show notes did not mention India, Kolhapur or the people who make the form.","level":"documented","position":2},{"id":"case-kolhapuri-prada:q3","case_id":"case-kolhapuri-prada","q":"Was cultural origin credited?","a":"Not at first. Prada acknowledged the inspiration in a letter only after public criticism, in late June 2025.","level":"documented","position":3},{"id":"case-kolhapuri-prada:q4","case_id":"case-kolhapuri-prada","q":"Were artisan communities involved?","a":"Not in the runway design. Afterwards a Prada team visited Kolhapur's workshops (July 2025), and the 2026 collection was reported as made by artisans in Maharashtra and Karnataka under an agreement with the two state corporations.","level":"documented","position":4},{"id":"case-kolhapuri-prada:q5","case_id":"case-kolhapuri-prada","q":"What changed after public criticism?","a":"An acknowledgement, a workshop visit, an MoU with the GI proprietors, a product named for the tradition, and a funded three-year training programme for 180 artisans with NIFT and KILT among the partners. How its benefits reach individual makers is not yet documented.","level":"documented","position":5}]$cp$::jsonb)
  on conflict do nothing;

insert into case_question_sources ("question_id", "source_id", "position")
  select "question_id", "source_id", "position" from jsonb_populate_recordset(null::case_question_sources, $cp$[{"question_id":"case-kolhapuri-prada:q0","source_id":"khaleej-prada-debate","position":0},{"question_id":"case-kolhapuri-prada:q0","source_id":"open-prada-kolhapuri","position":1},{"question_id":"case-kolhapuri-prada:q1","source_id":"gi-169","position":0},{"question_id":"case-kolhapuri-prada:q1","source_id":"open-prada-kolhapuri","position":1},{"question_id":"case-kolhapuri-prada:q2","source_id":"bt-prada-admits","position":0},{"question_id":"case-kolhapuri-prada:q2","source_id":"open-prada-kolhapuri","position":1},{"question_id":"case-kolhapuri-prada:q3","source_id":"bt-prada-admits","position":0},{"question_id":"case-kolhapuri-prada:q3","source_id":"tribune-prada-ack","position":1},{"question_id":"case-kolhapuri-prada:q4","source_id":"bt-prada-visit","position":0},{"question_id":"case-kolhapuri-prada:q4","source_id":"fu-prada-mou","position":1},{"question_id":"case-kolhapuri-prada:q4","source_id":"wwd-prada-2026","position":2},{"question_id":"case-kolhapuri-prada:q5","source_id":"fu-prada-mou","position":0},{"question_id":"case-kolhapuri-prada:q5","source_id":"wwd-prada-2026","position":1},{"question_id":"case-kolhapuri-prada:q5","source_id":"brut-prada-2026","position":2}]$cp$::jsonb)
  on conflict do nothing;

insert into events ("id", "tradition_id", "case_id", "year", "month", "day", "approx", "date_label", "title", "body", "level", "place_id", "tag", "media_id", "position")
  select "id", "tradition_id", "case_id", "year", "month", "day", "approx", "date_label", "title", "body", "level", "place_id", "tag", "media_id", "position" from jsonb_populate_recordset(null::events, $cp$[{"id":"kol-t-origin","tradition_id":"trad-kolhapuri","case_id":null,"year":1200,"month":null,"day":null,"approx":true,"date_label":"c. 12th–13th century (claimed)","title":"An origin before the name","body":"Popular histories place the chappal's beginnings here, before it was called 'Kolhapuri'. A competing account credits a single family with the design in 1920. Neither claim rests on evidence we could verify.","level":"disputed","place_id":null,"tag":"origin","media_id":null,"position":0},{"id":"kol-t-shahu","tradition_id":"trad-kolhapuri","case_id":null,"year":1910,"month":null,"day":null,"approx":true,"date_label":"Early 20th century (as recounted)","title":"Royal patronage in princely Kolhapur","body":"Accounts credit the rulers of Kolhapur — most often Chhatrapati Shahu Maharaj — with encouraging the trade and opening tanning centres. Which ruler, and when, needs archival confirmation.","level":"interpretation","place_id":"kolhapur","tag":"patronage","media_id":null,"position":1},{"id":"kol-t-gi-filed","tradition_id":"trad-kolhapuri","case_id":null,"year":2009,"month":5,"day":4,"approx":false,"date_label":"4 May 2009","title":"A joint GI application","body":"An application to register 'Kolhapuri Chappal' as a geographical indication is filed (No. 169), covering districts in both Maharashtra and Karnataka. Some secondary sources give 4 April 2009.","level":"documented","place_id":null,"tag":"recognition","media_id":null,"position":2},{"id":"kol-t-bata","tradition_id":"trad-kolhapuri","case_id":null,"year":2013,"month":7,"day":null,"approx":false,"date_label":"July 2013","title":"Behind museum glass in Toronto","body":"A late-20th-century chappal from Kolhapur is photographed on display at the Bata Shoe Museum — the craft named and placed in a museum, years before the runway.","level":"documented","place_id":"bata-museum","tag":"exhibition","media_id":"bata-chappal-453","position":3},{"id":"kol-t-gi-journal","tradition_id":"trad-kolhapuri","case_id":null,"year":2018,"month":8,"day":9,"approx":false,"date_label":"9 August 2018","title":"Advertised in the GI Journal","body":"The application is published in GI Journal No. 109, listing four districts in each state as the area of production.","level":"documented","place_id":null,"tag":"recognition","media_id":null,"position":4},{"id":"kol-t-gi-cert","tradition_id":"trad-kolhapuri","case_id":null,"year":2018,"month":12,"day":11,"approx":false,"date_label":"11 December 2018","title":"Registered as a geographical indication","body":"The registry records certificate No. 329 for Kolhapuri Chappal. News of the registration was widely reported in mid-2019.","level":"documented","place_id":null,"tag":"recognition","media_id":null,"position":5},{"id":"kol-t-runway","tradition_id":"trad-kolhapuri","case_id":null,"year":2025,"month":6,"day":null,"approx":false,"date_label":"June 2025","title":"The Milan runway","body":"Prada's Men's Spring/Summer 2026 show in Milan features open-toed leather sandals. Show notes call them 'leather sandals' and make no reference to India.","level":"documented","place_id":"milan","tag":"runway","media_id":null,"position":6},{"id":"kol-t-ack","tradition_id":"trad-kolhapuri","case_id":null,"year":2025,"month":6,"day":27,"approx":true,"date_label":"Late June 2025","title":"Acknowledgement after criticism","body":"After criticism from artisans, designers and Maharashtra's chamber of commerce, Prada acknowledges in a letter that the sandals were inspired by traditional Indian handcrafted footwear.","level":"documented","place_id":null,"tag":"response","media_id":null,"position":7},{"id":"kol-t-visit","tradition_id":"trad-kolhapuri","case_id":null,"year":2025,"month":7,"day":15,"approx":false,"date_label":"15 July 2025","title":"A visit to the workshops","body":"A Prada technical team visits Kolhapur's chappal-making cluster, observes production and meets artisans.","level":"documented","place_id":"kolhapur","tag":"collaboration","media_id":null,"position":8},{"id":"kol-t-pil","tradition_id":"trad-kolhapuri","case_id":null,"year":2025,"month":7,"day":16,"approx":false,"date_label":"16 July 2025","title":"A court declines to decide","body":"The Bombay High Court dismisses a public interest litigation against Prada, questioning the petitioners' standing and leaving registered GI proprietors free to pursue remedies. It makes no finding on infringement.","level":"documented","place_id":"mumbai","tag":"legal","media_id":null,"position":9},{"id":"kol-t-mou","tradition_id":"trad-kolhapuri","case_id":null,"year":2025,"month":12,"day":11,"approx":true,"date_label":"10–11 December 2025","title":"An agreement with the GI proprietors","body":"Prada signs a memorandum of understanding in Mumbai with LIDCOM (Maharashtra) and LIDKAR (Karnataka) for a limited-edition sandal collection made in India. Reports differ on whether it was signed on 10 or 11 December.","level":"documented","place_id":"mumbai","tag":"collaboration","media_id":null,"position":10},{"id":"kol-t-launch","tradition_id":"trad-kolhapuri","case_id":null,"year":2026,"month":4,"day":27,"approx":false,"date_label":"27 April 2026","title":"'Made in India x Inspired by Kolhapuri Chappals'","body":"Prada announces the collection — reported as about 2,000 pairs made by artisans in Maharashtra and Karnataka — with a three-year training programme for 180 artisans.","level":"documented","place_id":null,"tag":"collaboration","media_id":null,"position":11},{"id":"case-kolhapuri-prada:c1","tradition_id":"trad-kolhapuri","case_id":"case-kolhapuri-prada","year":1200,"month":null,"day":null,"approx":true,"date_label":"Centuries (dates disputed)","title":"A regional craft","body":"Hand-stitched leather chappals are made by Charmakar communities across southern Maharashtra and northern Karnataka.","level":"documented","place_id":null,"tag":"origin","media_id":null,"position":0},{"id":"case-kolhapuri-prada:c2","tradition_id":"trad-kolhapuri","case_id":"case-kolhapuri-prada","year":2018,"month":12,"day":11,"approx":false,"date_label":"2018–2019","title":"The name is protected","body":"'Kolhapuri Chappal' is registered as a geographical indication for eight districts in two states.","level":"documented","place_id":null,"tag":"recognition","media_id":null,"position":1},{"id":"case-kolhapuri-prada:c3","tradition_id":"trad-kolhapuri","case_id":"case-kolhapuri-prada","year":2025,"month":6,"day":null,"approx":false,"date_label":"June 2025","title":"Shown as 'leather sandals'","body":"The sandals appear on the Milan runway; the show notes make no reference to India.","level":"documented","place_id":null,"tag":"runway","media_id":null,"position":2},{"id":"case-kolhapuri-prada:c4","tradition_id":"trad-kolhapuri","case_id":"case-kolhapuri-prada","year":2025,"month":6,"day":null,"approx":false,"date_label":"June 2025","title":"Public concern","body":"Artisans, designers and politicians in India object to the missing credit; Maharashtra's chamber of commerce writes to the company.","level":"documented","place_id":null,"tag":"response","media_id":null,"position":3},{"id":"case-kolhapuri-prada:c5","tradition_id":"trad-kolhapuri","case_id":"case-kolhapuri-prada","year":2025,"month":6,"day":null,"approx":false,"date_label":"Late June 2025","title":"Acknowledgement","body":"Prada's head of corporate social responsibility replies that the design was inspired by traditional Indian handcrafted footwear.","level":"documented","place_id":null,"tag":"response","media_id":null,"position":4},{"id":"case-kolhapuri-prada:c6","tradition_id":"trad-kolhapuri","case_id":"case-kolhapuri-prada","year":2026,"month":4,"day":null,"approx":false,"date_label":"July 2025 – April 2026","title":"From acknowledgement to agreement","body":"A technical team visits Kolhapur; a court declines a public-interest case on standing; an MoU is signed with LIDCOM and LIDKAR; a made-in-India collection and artisan training programme follow.","level":"documented","place_id":null,"tag":"collaboration","media_id":null,"position":5},{"id":"mad-t-legend","tradition_id":"trad-madhubani","case_id":null,"year":-1000,"month":null,"day":null,"approx":true,"date_label":"Legend","title":"Painting for Sita's wedding","body":"In the widely told story, King Janaka has his kingdom painted for his daughter Sita's wedding. It is a tradition about origins, not a dated event.","level":"community","place_id":"janakpur","tag":"origin","media_id":null,"position":0},{"id":"mad-t-1934","tradition_id":"trad-madhubani","case_id":null,"year":1934,"month":null,"day":null,"approx":false,"date_label":"1934","title":"Revealed by an earthquake","body":"After the Bihar–Nepal earthquake, W. G. Archer sees paintings on the exposed inner walls of damaged homes, and later photographs them.","level":"documented","place_id":"madhubani","tag":"exchange","media_id":null,"position":1},{"id":"mad-t-1949","tradition_id":"trad-madhubani","case_id":null,"year":1949,"month":null,"day":null,"approx":false,"date_label":"1949","title":"'Maithil painting' in Marg","body":"Archer's article in Marg brings the painting to scholarly attention — and shapes how it is classified for decades.","level":"documented","place_id":null,"tag":"exchange","media_id":null,"position":2},{"id":"mad-t-1966","tradition_id":"trad-madhubani","case_id":null,"year":1966,"month":null,"day":null,"approx":true,"date_label":"c. 1966–68","title":"From walls to paper","body":"During a severe drought, the All India Handicrafts Board encourages women to paint on paper for sale. Some sources date the start of the programme to 1964.","level":"documented","place_id":"new-delhi","tag":"craft","media_id":null,"position":3},{"id":"mad-t-1975","tradition_id":"trad-madhubani","case_id":null,"year":1975,"month":null,"day":null,"approx":false,"date_label":"1975","title":"A painter named nationally","body":"Jagdamba Devi becomes the first Mithila painter to receive the Padma Shri.","level":"documented","place_id":null,"tag":"recognition","media_id":null,"position":4},{"id":"mad-t-1982","tradition_id":"trad-madhubani","case_id":null,"year":1982,"month":null,"day":null,"approx":false,"date_label":"1982","title":"A museum in snowy Niigata","body":"Tokio Hasegawa opens the Mithila Museum in Tokamachi, Japan, in a converted elementary school. It grows into one of the largest collections of Mithila painting anywhere.","level":"documented","place_id":"tokamachi","tag":"exhibition","media_id":null,"position":5},{"id":"mad-t-2007","tradition_id":"trad-madhubani","case_id":null,"year":2007,"month":5,"day":16,"approx":false,"date_label":"16 May 2007","title":"Registered as a geographical indication","body":"'Madhubani Paintings' is registered as a GI for Bihar, on an application by the state's Director of Industries filed in 2005.","level":"documented","place_id":null,"tag":"recognition","media_id":null,"position":6},{"id":"phk-t-undated","tradition_id":"trad-phulkari","case_id":null,"year":1800,"month":null,"day":null,"approx":true,"date_label":"Before 1900 (undated)","title":"Origins we cannot yet date","body":"Claims about phulkari's age vary widely. We have not found a reliable source for when it began.","level":"unverified","place_id":null,"tag":"origin","media_id":null,"position":0},{"id":"phk-t-1900","tradition_id":"trad-phulkari","case_id":null,"year":1900,"month":null,"day":null,"approx":true,"date_label":"c. 1900","title":"A portrait in phulkari","body":"A photograph from Patiala shows a woman draped in phulkari — an archival glimpse of how it was worn.","level":"documented","place_id":"patiala","tag":"craft","media_id":"phulkari-patiala-1900","position":1},{"id":"phk-t-1947","tradition_id":"trad-phulkari","case_id":null,"year":1947,"month":null,"day":null,"approx":false,"date_label":"1947","title":"Punjab divided","body":"Partition separates the region and disrupts the networks that sustained the embroidery.","level":"interpretation","place_id":null,"tag":"disruption","media_id":null,"position":2},{"id":"phk-t-2005","tradition_id":"trad-phulkari","case_id":null,"year":2005,"month":3,"day":14,"approx":false,"date_label":"14 March 2005","title":"A GI application","body":"Punjab Small Industries & Export Corporation applies to register Phulkari as a geographical indication for Punjab, Haryana and Rajasthan.","level":"documented","place_id":null,"tag":"recognition","media_id":null,"position":3},{"id":"phk-t-2010","tradition_id":"trad-phulkari","case_id":null,"year":2010,"month":10,"day":22,"approx":false,"date_label":"22 October 2010","title":"Registered","body":"The registry issues certificate No. 145. Many secondary sources date this to 2011.","level":"documented","place_id":null,"tag":"recognition","media_id":null,"position":4},{"id":"phk-t-2017","tradition_id":"trad-phulkari","case_id":null,"year":2017,"month":3,"day":12,"approx":false,"date_label":"12 March – 9 July 2017","title":"Philadelphia","body":"The Philadelphia Museum of Art opens what was described as the first major US exhibition of phulkari, including its losses at Partition and its use in contemporary fashion.","level":"documented","place_id":"philadelphia","tag":"exhibition","media_id":null,"position":5},{"id":"wrl-t-ritual","tradition_id":"trad-warli","case_id":null,"year":1900,"month":null,"day":null,"approx":true,"date_label":"Undated","title":"Painting for ritual","body":"Warli painting is described as ritual wall painting, renewed for occasions. Its age is not documented in our sources.","level":"unverified","place_id":"dahanu","tag":"origin","media_id":null,"position":0},{"id":"wrl-t-1989","tradition_id":"trad-warli","case_id":null,"year":1989,"month":null,"day":null,"approx":false,"date_label":"1989","title":"Paris","body":"Jivya Soma Mashe's work is shown in 'Magiciens de la Terre' at the Centre Pompidou.","level":"documented","place_id":"paris","tag":"exhibition","media_id":null,"position":1},{"id":"wrl-t-2011","tradition_id":"trad-warli","case_id":null,"year":2011,"month":null,"day":null,"approx":false,"date_label":"2011","title":"Honour and application","body":"Mashe receives the Padma Shri. AYUSH, a Dahanu-based Adivasi organisation, files for a geographical indication.","level":"documented","place_id":null,"tag":"recognition","media_id":null,"position":2},{"id":"wrl-t-2014","tradition_id":"trad-warli","case_id":null,"year":2014,"month":3,"day":31,"approx":false,"date_label":"31 March 2014","title":"Registered as a GI","body":"Warli Painting is registered (certificate No. 208) for goods in classes covering paper, furniture and clothing.","level":"documented","place_id":null,"tag":"recognition","media_id":null,"position":3},{"id":"wrl-t-2018","tradition_id":"trad-warli","case_id":null,"year":2018,"month":5,"day":15,"approx":false,"date_label":"15 May 2018","title":"Jivya Soma Mashe dies","body":"The painter dies at home in Dahanu.","level":"documented","place_id":"dahanu","tag":null,"media_id":null,"position":4},{"id":"ajk-t-indus","tradition_id":"trad-ajrakh","case_id":null,"year":-2500,"month":null,"day":null,"approx":true,"date_label":"c. 2500 BCE (claimed)","title":"A resemblance, not a record","body":"The trefoil robe on Mohenjo-daro's 'priest-king' is often cited as ajrakh's ancestor. Visual similarity is the only evidence offered.","level":"disputed","place_id":"mohenjo-daro","tag":"origin","media_id":null,"position":0},{"id":"ajk-t-migration","tradition_id":"trad-ajrakh","case_id":null,"year":1550,"month":null,"day":null,"approx":true,"date_label":"16th–17th century (accounts differ)","title":"From Sindh to Kutch","body":"Khatri families are said to have moved from Sindh to Kutch, settling in places such as Dhamadka. Accounts of when and why differ.","level":"disputed","place_id":"dhamadka","tag":"migration","media_id":null,"position":1},{"id":"ajk-t-2001","tradition_id":"trad-ajrakh","case_id":null,"year":2001,"month":1,"day":26,"approx":false,"date_label":"26 January 2001","title":"The earthquake and Ajrakhpur","body":"The Kutch earthquake — and water problems in Dhamadka — push many printing families to a new settlement, Ajrakhpur, near Bhuj.","level":"documented","place_id":"ajrakhpur","tag":"disruption","media_id":null,"position":2},{"id":"ajk-t-2023","tradition_id":"trad-ajrakh","case_id":null,"year":2023,"month":1,"day":31,"approx":false,"date_label":"31 January 2023","title":"A GI application from Ajrakhpur","body":"Ajarakhpur Hastkala Vikas Sangathan applies to register 'Kutch Ajrakh Print of Gujarat'.","level":"documented","place_id":null,"tag":"recognition","media_id":null,"position":3},{"id":"ajk-t-2024","tradition_id":"trad-ajrakh","case_id":null,"year":2024,"month":4,"day":22,"approx":false,"date_label":"April 2024","title":"Kutch Ajrakh registered","body":"The certificate is handed to artisans; coverage frames it as recognition of a centuries-old craft.","level":"documented","place_id":null,"tag":"recognition","media_id":null,"position":4},{"id":"sadu-t-2011","tradition_id":"trad-sadu","case_id":null,"year":2011,"month":null,"day":null,"approx":false,"date_label":"2011","title":"Urgent safeguarding","body":"UNESCO inscribes Al Sadu on the List of Intangible Cultural Heritage in Need of Urgent Safeguarding.","level":"documented","place_id":null,"tag":"recognition","media_id":null,"position":0},{"id":"sadu-t-2020","tradition_id":"trad-sadu","case_id":null,"year":2020,"month":12,"day":null,"approx":false,"date_label":"December 2020","title":"A report, and advice","body":"UNESCO's committee invites the UAE to teach Al Sadu in schools, secure raw materials and natural dyeing, and watch for over-commercialisation.","level":"documented","place_id":null,"tag":"recognition","media_id":null,"position":1},{"id":"sadu-t-2022","tradition_id":"trad-sadu","case_id":null,"year":2022,"month":null,"day":null,"approx":false,"date_label":"2022","title":"A sister craft inscribed","body":"Al Talli, the UAE's traditional braided embroidery, joins UNESCO's Representative List.","level":"documented","place_id":null,"tag":"recognition","media_id":null,"position":2},{"id":"sadu-t-2025","tradition_id":"trad-sadu","case_id":null,"year":2025,"month":12,"day":null,"approx":false,"date_label":"December 2025","title":"New Delhi","body":"Meeting in New Delhi, UNESCO's committee transfers Al Sadu to the Representative List and selects the UAE's safeguarding programme for the Register of Good Safeguarding Practices.","level":"documented","place_id":"new-delhi","tag":"recognition","media_id":null,"position":3}]$cp$::jsonb)
