insert into process_steps ("id", "tradition_id", "title", "detail", "level", "position")
  select "id", "tradition_id", "title", "detail", "level", "position" from jsonb_populate_recordset(null::process_steps, $cp$[{"id":"trad-kolhapuri:step:0","tradition_id":"trad-kolhapuri","title":"Skiving","detail":"Leather is thinned and evened for each part of the chappal.","level":"unverified","position":0},{"id":"trad-kolhapuri:step:1","tradition_id":"trad-kolhapuri","title":"Pattern & cutting","detail":"Soles, straps and the toe loop are cut by hand from templates.","level":"unverified","position":1},{"id":"trad-kolhapuri:step:2","tradition_id":"trad-kolhapuri","title":"Layering the sole","detail":"Sole layers and heel are built up and attached to the upper.","level":"unverified","position":2},{"id":"trad-kolhapuri:step:3","tradition_id":"trad-kolhapuri","title":"Stitching","detail":"Parts are joined with thread — no nails.","level":"documented","position":3},{"id":"trad-kolhapuri:step:4","tradition_id":"trad-kolhapuri","title":"Braiding & punching","detail":"Strips are braided and punched into the decorative upper.","level":"unverified","position":4},{"id":"trad-kolhapuri:step:5","tradition_id":"trad-kolhapuri","title":"Finishing & polish","detail":"Edges are trimmed, surfaces decorated and polished.","level":"unverified","position":5},{"id":"trad-madhubani:step:0","tradition_id":"trad-madhubani","title":"Border first","detail":"Compositions are commonly framed with a decorated border.","level":"unverified","position":0},{"id":"trad-madhubani:step:1","tradition_id":"trad-madhubani","title":"Double outline","detail":"Figures are drawn in double lines, filled with hatching (kachni) or colour (bharni).","level":"interpretation","position":1},{"id":"trad-madhubani:step:2","tradition_id":"trad-madhubani","title":"No empty ground","detail":"Spaces are filled with flowers, fish, birds and geometric pattern.","level":"unverified","position":2},{"id":"trad-phulkari:step:0","tradition_id":"trad-phulkari","title":"Count the weave","detail":"The design follows the threads