insert into related_traditions ("tradition_id", "related_id", "reason", "position")
  select "tradition_id", "related_id", "reason", "position" from jsonb_populate_recordset(null::related_traditions, $cp$[{"tradition_id":"trad-kolhapuri","related_id":"trad-phulkari","reason":"Another tradition that met fashion — in a museum exhibition that placed phulkari beside designer garments.","position":0},{"tradition_id":"trad-kolhapuri","related_id":"trad-warli","reason":"Also from Maharashtra. Its GI was pursued by an Adivasi organisation after its imagery circulated online without context.","position":1},{"tradition_id":"trad-kolhapuri","related_id":"trad-ajrakh","reason":"A hand process — block, dye, wash, repeat — whose rising demand is changing the craft that makes it.","position":2},{"tradition_id":"trad-madhubani","related_id":"trad-warli","reason":"Another wall painting tradition that moved onto paper in the 1960s–70s and made individual painters famous.","position":0},{"tradition_id":"trad-madhubani","related_id":"trad-phulkari","reason":"Also a women's art made for weddings, and also divided by a modern border.","position":1},{"tradition_id":"trad-phulkari","related_id":"trad-ajrakh","reason":"Another textile tradition shared across the India–Pakistan border.","position":0},{"tradition_id":"trad-phulkari","related_id":"trad-madhubani","reason":"Another women's art made for weddings, and another region divided by a modern border.","position":1},{"tradition_id":"trad-phulkari","related_id":"trad-kolhapuri","reason":"Another tradition that met global fashion — and the question of credit.","position":2},{"tradition_id":"trad-warli","related_id":"trad-madhubani","reason":"Another wall painting tradition carried onto paper, with painters who became nationally known.","position":0},{"tradition_id":"trad-warli","related_id":"trad-kolhapuri","reason":"Also from Maharashtra; another tradition whose name is protected by its makers' organisations.","position":1},{"tradition_id":"trad-ajrakh","related_id":"trad-phulkari","reason":"Another textile tradition shared across the India–Pakistan border.","position":0},{"tradition_id":"trad-ajrakh","related_id":"trad-sadu","reason":"Another textile whose geometry carries community identity — across the Arabian Sea.","position":1},{"tradition_id":"trad-sadu","related_id":"trad-ajrakh","reason":"Another textile whose geometry carries identity — across the Arabian Sea in Sindh and Kutch.","position":0},{"tradition_id":"trad-sadu","related_id":"trad-phulkari","reason":"Another women's textile skill passed on by watching, together.","position":1}]$cp$::jsonb)
  on conflict do nothing;

insert into relationships ("id", "tradition_id", "from_place", "to_place", "kind", "title", "description", "level", "year")
  select "id", "tradition_id", "from_place", "to_place", "kind", "title", "description", "level", "year" from jsonb_populate_recordset(null::relationships, $cp$[{"id":"rel-kol-gi","tradition_id":"trad-kolhapuri","from_place":"kolhapur","to_place":"belagavi","kind":"shared-practice","title":"One name, two states","description":"The Kolhapuri Chappal GI covers four districts in Maharashtra and four in Karnataka — a craft shared across a state border.","level":"documented","year":"2018"},{"id":"rel-kol-milan","tradition_id":"trad-kolhapuri","from_place":"kolhapur","to_place":"milan","kind":"commercial-adaptation","title":"To the Milan runway","description":"Sandals widely recognised as Kolhapuri in style appear in Prada's Men's SS26 show as 'leather sandals'; inspiration is acknowledged after criticism.","level":"documented","year":"2025"},{"id":"rel-kol-visit","tradition_id":"trad-kolhapuri","from_place":"milan","to_place":"kolhapur","kind":"collaboration","title":"Back to the workshops","description":"A Prada technical team visits Kolhapur's chappal cluster and meets artisans.","level":"documented","year":"2025"},{"id":"rel-kol-mou","tradition_id":"trad-kolhapuri","from_place":"mumbai","to_place":"milan","kind":"collaboration","title":"An agreement signed in Mumbai","description":"Prada signs an MoU with LIDCOM and LIDKAR for a limited collection made in India, launched in 2026.","level":"documented","year":"2025–26"},{"id":"rel-kol-bata","tradition_id":"trad-kolhapuri","from_place":"kolhapur","to_place":"bata-museum","kind":"exhibition","title":"Into a museum in Toronto","description":"A late-20th-century Kolhapur chappal on display at the Bata Shoe Museum, labelled by place.","level":"documented","year":"2013"},{"id":"rel-mad-nepal","tradition_id":"trad-madhubani","from_place":"madhubani","to_place":"janakpur","kind":"shared-practice","title":"One region, two countries","description":"The Mithila cultural region spans northern Bihar and Nepal's Madhesh around Janakpur.","level":"documented","year":null},{"id":"rel-mad-delhi","tradition_id":"trad-madhubani","from_place":"madhubani","to_place":"new-delhi","kind":"recognition","title":"From walls to paper","description":"A 1960s drought-relief programme of the All India Handicrafts Board brings Mithila painting onto paper and to national markets.","level":"documented","year":"c. 1966"},{"id":"rel-mad-japan","tradition_id":"trad-madhubani","from_place":"madhubani","to_place":"tokamachi","kind":"exhibition","title":"A museum in Japan","description":"Tokio Hasegawa founds the Mithila Museum in Tokamachi, Niigata, and builds a decades-long relationship with Mithila painters.","level":"documented","year":"1982"},{"id":"rel-phk-punjab","tradition_id":"trad-phulkari","from_place":"amritsar","to_place":"lahore","kind":"shared-practice","title":"Punjab, divided in 1947","description":"Phulkari belongs to undivided Punjab and is shared by India and Pakistan.","level":"documented","year":"1947"},{"id":"rel-phk-pma","tradition_id":"trad-phulkari","from_place":"patiala","to_place":"philadelphia","kind":"exhibition","title":"Philadelphia, 2017","description":"The first major US exhibition of phulkari, which also placed it beside contemporary fashion.","level":"documented","year":"2017"},{"id":"rel-wrl-paris","tradition_id":"trad-warli","from_place":"dahanu","to_place":"paris","kind":"exhibition","title":"Magiciens de la Terre","description":"Jivya Soma Mashe's Warli painting is exhibited at the Centre Pompidou.","level":"documented","year":"1989"},{"id":"rel-ajk-migration","tradition_id":"trad-ajrakh","from_place":"sindh","to_place":"dhamadka","kind":"migration","title":"Khatri families from Sindh","description":"Kutch printing families trace their roots to Sindh; accounts of when they moved differ (16th century to about 400 years ago).","level":"community","year":null},{"id":"rel-ajk-2001","tradition_id":"trad-ajrakh","from_place":"dhamadka","to_place":"ajrakhpur","kind":"migration","title":"After the 2001 earthquake","description":"Printing families move from Dhamadka to the new settlement of Ajrakhpur near Bhuj.","level":"documented","year":"2001"},{"id":"rel-ajk-barmer","tradition_id":"trad-ajrakh","from_place":"kutch","to_place":"barmer","kind":"shared-practice","title":"Printed in Barmer too","description":"Ajrakh is also printed in Barmer, Rajasthan. Details of the relationship between centres need documenting.","level":"unverified","year":null},{"id":"rel-ajk-indus","tradition_id":"trad-ajrakh","from_place":"mohenjo-daro","to_place":"sindh","kind":"visual-similarity","title":"The 'priest-king' robe","description":"A trefoil-patterned robe on a Mohenjo-daro sculpture resembles some ajrakh motifs. Resemblance is not evidence of continuous tradition, and we do not present it as influence.","level":"disputed","year":null},{"id":"rel-sadu-delhi","tradition_id":"trad-sadu","from_place":"al-ain","to_place":"new-delhi","kind":"recognition","title":"A UAE decision taken in India","description":"UNESCO's 20th committee session, in New Delhi, transfers Al Sadu to the Representative List.","level":"documented","year":"2025"}]$cp$::jsonb)
  on conflict do nothing;

