insert into trails ("slug", "title", "kicker", "intro", "accent", "position")
  select "slug", "title", "kicker", "intro", "accent", "position" from jsonb_populate_recordset(null::trails, $cp$[{"slug":"crafted-by-hand","title":"Crafted by Hand","kicker":"Trail I","intro":"Four traditions, four sets of hands: stitching leather, printing and dyeing, spinning and weaving, darning in silk. Follow the making, not just the made.","accent":"terracotta","position":0},{"slug":"threads-across-borders","title":"Threads Across Borders","kicker":"Trail II","intro":"Three traditions that modern borders cut through — Punjab, Sindh and Kutch, Mithila. None of them can be filed under one country without losing part of its story.","accent":"indigo","position":1},{"slug":"tradition-meets-the-runway","title":"Tradition Meets the Runway","kicker":"Trail III","intro":"When craft enters fashion, what travels — and what is left behind? One documented case, one museum, one market in flux.","accent":"burgundy","position":2},{"slug":"from-walls-to-paper","title":"From Walls to Paper","kicker":"Trail IV","intro":"Two painting traditions made for walls and rituals, which moved onto paper in the 20th century — and turned anonymous painters into named artists.","accent":"forest","position":3}]$cp$::jsonb)
  on conflict do nothing;

